\label{defin of resonance types 0,12}{\rm{\bf (Resonant types at elliptic thresholds).}}
 Let $H=-\Delta+V$ on $\mathbb{Z}^3$ and $|V(n)|\lesssim \left<n\right>^{-\beta}$ for some $\beta>2$. Then, for $\lambda \in \{0,12\}$, we have 
 \vskip0.2cm
\begin{itemize}
\item[{\rm(i)}] $\lambda$ is \textbf{a regular point of $H$} if $H\phi=\lambda\phi$ has only the zero solution in $\bigcap\limits_{s>1/2} \ell^{2, -s}(\mathbb{Z}^3)$.
\vskip0.15cm
\item [{\rm(ii)}] $\lambda$ is \textbf{a resonance of $H$} if  $H\phi=\lambda\phi$ has a non-zero solution in $\bigcap\limits_{s>1/2} \ell^{2, -s}(\mathbb{Z}^3)$ but only the zero solution in $\ell^{2}(\mathbb{Z}^3)$.
\vskip0.15cm
\item [{\rm(iii)}] $\lambda$ is \textbf{an eigenvalue of $H$} if  $H\phi=\lambda\phi$ has a non-zero solution in $\ell^2(\mathbb{Z}^3)$.
\end{itemize}

\label{defin of resonance types 4,8}{\rm{\bf (Resonant types at hyperbolic thresholds).}}
 Let $H=-\Delta+V$ on $\mathbb{Z}^3$ and $|V(n)|\lesssim \left<n\right>^{-\beta}$ for some $\beta>2$. Then, for $\lambda \in \{4,8\}$, we have 
 \vskip0.2cm
\begin{itemize}
\item[{\rm(i)}] $\lambda$ is \textbf{a regular point of $H$} if $\phi+(-\Delta-\lambda\mp i0)^{-1}V\phi=0$ has only the zero solution in $\ell^{2,-1}(\mathbb{Z}^3)$.
\vskip0.15cm
\item [{\rm(ii)}] $\lambda$ is \textbf{a resonance of $H$} if $\phi+(-\Delta-\lambda\mp i0)^{-1}V\phi=0$ has a non-zero solution in $\ell^{2,-1}(\mathbb{Z}^3)$ but only the zero solution in $\ell^{2}(\mathbb{Z}^3)$.
\vskip0.15cm
\item [{\rm(iii)}] $\lambda$ is \textbf{an eigenvalue of $H$} if $\phi+(-\Delta-\lambda\mp i0)^{-1}V\phi=0$ has a non-zero solution in $\ell^2(\mathbb{Z}^3)$.
\end{itemize}

\label{Asymptotic expansion theorem_0}
 Let $H=-\Delta+V$ with $|V(n)|\lesssim \left<n\right>^{-\beta}$ for some $\beta>0$. 
Then the following asymptotic expansions hold in $\mathcal{B}(\sigma,-\sigma)$ as $|\omega|\rightarrow 0$ with $\arg\omega\in(0,2\pi)$. 
\begin{itemize}
\item[{\rm(i)}] If $0$ {\rm(}resp. $12${\rm)} is a regular point of $H$ and $\beta>3$, then for any $\sigma>\frac{3}{2}$, 
\begin{equation}\label{(t)asy expan of regular 0}
R_V(\omega)=\mathbb{A}_0+O(\omega^{\frac{1}{2}}),\qquad
R_V(12-\omega)=\mathscr{A}_0+O(\omega^{\frac{1}{2}}).
\end{equation}
\item [{\rm(ii)}] If $0$ {\rm(}resp. $12${\rm)} is a resonance of $H$ and $\beta>5$, then for any $\sigma>\frac{5}{2}$, 
\begin{equation}\label{(t)asy expan of resonance 0}
R_V(\omega)=\mathbb{A}_1\omega^{-\frac{1}{2}}+O(1),\qquad 
R_V(12-\omega)=\mathscr{A}_1\omega^{-\frac{1}{2}}+O(1).
\end{equation}

\item [{\rm(iii)}] If $0$ {\rm(}resp. $12${\rm)} is an eigenvalue of $H$ and $\beta>7$, then for any $\sigma>\frac{7}{2}$, 
\begin{equation}\label{(t)asy expan of eigenvalue 0}
R_V(\omega)=-\mathcal{P}_0\omega^{-1}+O(\omega^{-\frac{1}{2}}),\qquad R_V(12-\omega)=\mathcal{P}_{12}\omega^{-1}+O(\omega^{-\frac{1}{2}}).
\end{equation}
\end{itemize}
Here $\mathcal{P}_0$ and $\mathcal{P}_{12}$ are the orthogonal projections onto the eigenspaces of $H$ at $0$ and $12$, respectively. Moreover, these expansions are twice differentiable in $\mathcal{B}(\sigma,-\sigma)$ with $\sigma>\frac{5}{2}$.

\label{Asymptotic expansion theorem_4}
 Let $H=-\Delta+V$ with $|V(n)|\lesssim \left<n\right>^{-\beta}$ for some $\beta>0$. 
Then the following asymptotic expansions hold in $\mathcal{B}(\sigma,-\sigma)$  as $|\omega|\rightarrow0$ with $\pm\operatorname{Im}\omega>0$.  
\begin{itemize}
\item[{\rm(i)}] If $4$ {\rm(}resp. $8${\rm)} is a regular point of $H$ and $\beta>7$, then for any $\sigma>\frac{7}{2}$,
\begin{equation}\label{(t)asy expan of regular 4}
R_V^{\pm}(4+\omega)=\mathbb{B}^{\pm}_0+\mathbb{B}^{\pm}_1\omega^{\frac{1}{2}}+O(\omega),\qquad
R_V^{\pm}(8-\omega)=\mathscr{B}^{\pm}_0+\mathscr{B}^{\pm}_1\omega^{\frac{1}{2}}+O(\omega).
\end{equation}
\item [{\rm(ii)}] If $4$ {\rm(}resp. $8${\rm)} is an eigenvalue of $H$ and $\beta>11$, then for any $\sigma>\frac{11}{2}$, 
\begin{equation}\label{(t)asy expan eigenvalue 4}
R_V^{\pm}(4+\omega)=-\mathcal{P}_4\omega^{-1}+O(\omega^{-\frac{1}{2}}),\qquad R_V^{\pm}(8-\omega)=\mathcal{P}_8\omega^{-1}+O(\omega^{-\frac{1}{2}}).
\end{equation}
\end{itemize}
Here $\mathcal{P}_4$ and $\mathcal{P}_{8}$ are are the orthogonal projections onto the eigenspaces of $H$ at $4$ and $8$, respectively. Moreover, these expansions are twice differentiable in $\mathcal{B}(\sigma,-\sigma)$ with $\sigma>\frac{11}{2}$.

\label{decay theorem}
Let $H=-\Delta+V$ with $|V(n)|\lesssim \left<n\right>^{-\beta}$ for $\beta>11$. Suppose that $H$ has no positive eigenvalues in the interval $\mathcal{I}=(0,4)\cup(4,8)\cup(8,12)$, and let $P_{ac}(H)$ denote the spectral projection onto the absolutely continuous spectrum space of $H$. Then the following decay estimates hold in $\mathcal{B}(\sigma,-\sigma)$ for any $\sigma>\frac{11}{2}$:
\begin{equation*}
    e^{-itH}P_{ac}(H)=\begin{cases}
        O( t^{-\frac{3}{2}}),& all\ 0,4,8,12 \  are\ regular\ points \ of \ H\\
        O( t^{-\frac{1}{2}}),&otherwise
    \end{cases},\quad t\rightarrow+\infty.
\end{equation*}

\label{lemma of R0 0}
Let $ N = 0, 1, 2\cdots$ and $\sigma > N +\frac{3}{2}.$ Then the following expansion holds in $\mathcal{B}(\sigma, -\sigma):$
\begin{equation}\label{expan of R0}
\ R_{0}(\omega) =\sum\limits_{k=0}^{N}A_k \omega^{k/2}+ O(\omega^{{(N+1)}/{2}}),\quad \left| \omega\right|\rightarrow0,\quad \arg\omega\in(0,2\pi).
\end{equation}
Here $A_{k}\in\ \mathcal{B}(s, -s)$ with $ s>k+\frac{1}{2}.$ Moreover, if $k$ is odd, the kernel $A_k(n-m)$ of $A_k$ is given by
\begin{equation*}
 A_k(n)=\frac{i(\frac{k-1}{2})!}{4\pi k!}\sum\limits_{\substack{k_1+k_2+k_3=\frac{k-1}{2}\\  k_1,k_2,k_3\in \mathbb{N}}} \prod\limits_{j=1}^{3}\frac{(\frac{1}{2}-n_j)_{k_j}(\frac{1}{2}+n_j)_{k_j}}{k_j!},\quad n=(n_1,n_2,n_3)\in\mathbb{Z}^3
\end{equation*}
with $(a)_{\ell}:=a(a+1)\cdots(a+\ell-1)$ for any integer $\ell\geq1$ and $ (a)_0=1$. In particular, $A_1(n)=\frac{i}{4\pi}$.

\label{lemma of free reso expan at 4}
{\rm(\cite[Proposition 2.6]{Kop09})}
Let $ N =-1, 0, 1,\cdots$ and $\sigma >2 N +\frac{7}{2}.$ Then the following expansion holds in $\mathcal{B}(\sigma, -\sigma):$
\begin{equation}\label{expan at 4}
R^{\pm}_{0}(4+\omega) =\sum\limits_{k=0}^{N}E^{\pm}_k\omega^{k}+ \sum\limits_{k=0}^{N}B^{\pm}_k\omega^{k+1/2}+O(\omega^{N+1}),\quad \left| \omega \right|\rightarrow0,\quad \pm\operatorname{Im} \omega>0,
\end{equation}
where the operators $E^{\pm}_{k},B^{\pm}_{k}\in \mathcal{B}(s, -s)$ with $ s>2k+\frac{3}{2}.$ Moreover, $E^-_k=(E^+_k)^*$ and $B^-_k=-(B^+_k)^*$.

{\rm 
As for the other two thresholds $8$ and $12$, by means of the unitary transform $$(\mathcal{U}\phi)(n)=(-1)^{n_1+n_2+n_3}\phi(n), \quad n=(n_1,n_2,n_3),$$ we have $R_0(12-4k-\omega)=-\mathcal{U} R_0(4k+\omega)\mathcal{U}$ for $k=0,1$, and therefore, 
\begin{align}
R_{0}(12-\omega) &=\sum\limits_{k=0}^{N}\mathcal{A}_k \omega^{k/2}+ O(\omega^{{(N+1)}/{2}}),\quad \left| \omega\right|\rightarrow0,\quad \arg\omega\in(0,2\pi),\label{expan of R012}\\
R^{\pm}_{0}(8-\omega) &=\sum\limits_{k=0}^{N}\mathcal{E}^{\pm}_k\omega^{k}+ \sum\limits_{k=0}^{N}\mathcal{B}^{\pm}_k\omega^{k+1/2}+O(\omega^{N+1}),\quad \left| \omega \right|\rightarrow0,\quad \pm \operatorname{Im} \omega>0,\label{expan of R08}
\end{align}
where $\mathcal{A}_{k}=-\mathcal{U} A_k\mathcal{U},\ \mathcal{E}^{\pm}_{k}=-\mathcal{U} E^{\pm}_k\mathcal{U}$ and $ \mathcal{B}^{\pm}_{k}=-\mathcal{U} B^{\pm}_k\mathcal{U}.$
}

\label{remark of free expan}\ \

{\rm {\bf(1)} At the threshold $0$, Kopylova \cite[Proposition 2.4]{Kop09} established the operator-valued expansion \eqref{expan of R0}. In her argument, the discrete symbol is locally replaced by its quadratic approximation $|\theta|^2$, which captures the structure of the expansion but does not yield explicit kernel formulas for the coefficients associated with the exact discrete symbol $$\mathcal{M}(\theta)=\sum\limits_{j=1}^{3}(2-2\cos\theta_j),\qquad \theta=(\theta_1,\theta_2,\theta_3)\in (-\pi,\pi]^3.$$ Since such kernel information is required in our subsequent analysis, we rederive the expansion using the exact discrete symbol and compute the odd-order kernels $A_{2k+1}(n)$ explicitly; see Proposition \ref{prop of Ak calcul}.
\vskip0.1cm
{\bf(2)} At the threshold $4$, we use the expansion in \cite[Proposition 2.6]{Kop09}, which is derived from the exact discrete symbol. The expansion there is stated for $\operatorname{Im}\omega>0$, while the corresponding expansion for $\operatorname{Im}\omega<0$ follows from the identity $R_0(4+\omega)=R_0^*(4+\overline{\omega}).$
The argument in \cite{Kop09} analyzes the contributions from the critical points, while the contribution from the noncritical region is not made explicit. For our purposes, we verify that the latter contributes only integer powers of $\omega$. It follows that the half-integer coefficients $B^{\pm}_k(n)$ are determined entirely by the three critical points. In particular, we need the explicit form of $B^{\pm}_0(n)$, which we compute as follows (see Proposition \ref{prop of B0 calcu}):
\begin{equation}\label{kernel B0pmn}
 B^{\pm}_0(n)=\frac{\mp}{4\pi}\big((-1)^{n_1}+(-1)^{n_2}+(-1)^{n_3}\big),\qquad n=(n_1,n_2,n_3)\in\mathbb{Z}^3.
\end{equation}

{\bf(3)} Moreover, the coefficients $A_0$ and $E_0^\pm$ can be identified with fundamental solutions of $-\Delta$ and $-\Delta-4$, respectively. More precisely, $(-\Delta )A_0=\delta_0$ and $(-\Delta-4)E^{\pm}_0=\delta_0$, where $\delta_0$ denotes the Kronecker delta. Their kernels are commonly referred to as the corresponding {\it Green functions}. Formally, the Green function at energy $\lambda$ admits the Fourier representation
\begin{equation*}
    G(\lambda,n)=(2\pi)^{-3}\int_{(-\pi,\pi]^3}\frac{e^{in\cdot\theta}}{\mathcal{M}(\theta)-\lambda}d\theta.
\end{equation*}

 In the Euclidean setting, such Green function information plays an important role in relating the inversion scheme for $M^{-1}(\omega)$ to the characterization of threshold eigenfunctions and resonances (see, e.g., \cite{JN01}). In higher-dimensional lattice settings, however, no comparably simple general kernel formulas are available, except in the one-dimensional case (cf. \cite{KKK06,IJ21}). This lack of explicit kernel information makes it difficult to relate the threshold subspaces obtained from the inversion scheme to actual threshold eigenfunctions and resonances.

In our case, the situation at the threshold $\lambda=0$ is more favorable. Since $(\mathcal{M}(\theta))^{-1}\sim|\theta|^{-2}$ near $\theta=0$ is integrable on $(-\pi,\pi]^3$, the Green function $G(0,n)$ is well defined. Moreover, Martinsson and Rodin \cite[Example 1.1]{MR02} obtained the asymptotic relation
\begin{equation}\label{relation of phi0 and g0}
    |G(0,n)-G_d(n)|\lesssim \frac{1}{|n|^3},\quad G_d(n)=\frac{1}{4\pi|n|},\quad n\neq0,
\end{equation}
where $G_d(n)$ is the continuum Green function of $-\Delta_{\mathbb{R}^3}$ evaluated at lattice points. Since $A_0\in\mathcal{B}(s,-s)$ for all $s>1/2$, we have $A_0(\cdot)\in\ell^{2,-s}(\mathbb{Z}^3)$ for all $s>1/2$. By \eqref{relation of phi0 and g0}, the same holds for $G(0,\cdot)$. Moreover, both are fundamental solutions of $-\Delta$. Therefore, we conclude that $A_0(n)=G(0,n)
$. We remark that this identity, together with \eqref{relation of phi0 and g0}, plays an important role in the subsequent analysis of $M^{-1}(\omega)$ and in the characterization of threshold resonances at $\lambda=0$ (see Lemma \ref{chara of solution and space}). 



The situation at the threshold $\lambda=4$ is different. No analogous asymptotic description of the corresponding Green function is available for our purposes. However, the coefficients $E_0^\pm$ can be identified with the boundary values of the free resolvent:
\begin{equation*}
    E^{\pm}_0=(-\Delta-4\mp i0)^{-1}\quad \text {on}\ \ \ell^{2,s}(\mathbb{Z}^3)\ \ \text {for}\ \  s>7/2.
\end{equation*}
This identification allows us to make use of the threshold analysis of Nomura and Taira \cite{NT20}, in particular their absence-of-resonance result at hyperbolic thresholds. Together with the structure obtained from the inversion scheme, their result provides a key ingredient in the characterization of the threshold space at $\lambda=4$ (see Lemma \ref{chara of solution and space 4}).
}

\label{chara of solution and space}
{\rm Let $H=-\Delta+V$ with $|V(n)|\lesssim\left<n\right>^{-\beta}$ for $\beta>7$. Then
\begin{itemize}
\item [{\rm(i)}]$f\in S_1\ell^2(\mathbb{Z}^3)\Longleftrightarrow \exists\ \phi\in \bigcap\limits_{s>1/2} \ell^{2, -s}(\mathbb{Z}^3)$ such that $H\phi=0$. Moreover, $f=Uv\phi$ and $\phi=-A_0vf$.
\vskip0.15cm
\item [{\rm(ii)}]$f\in S_2\ell^2(\mathbb{Z}^3)\Longleftrightarrow \exists\ \phi\in \ell^2(\mathbb{Z}^3)$ such that $H\phi=0$. Moreover, $f=Uv\phi$ and $\phi=-A_0vf$.
\end{itemize}
}

\label{remark of invertibility}
{\rm In particular, if $A$ is bounded on $\mathcal{H}$ and has closed range, $P$ is the orthogonal projection onto $\operatorname{Ker}A$, and $\operatorname{Ker}A^*=\operatorname{Ker}A$, then $A+P$ is invertible on $\mathcal{H}$. Moreover, we can obtain
$$(A+P)^{-1}P=P=P(A+P)^{-1}.$$
This criterion will be used repeatedly in the expansion of $M^{-1}(\omega)$. 
    }

We first show that all the operators $D_j$ are well-defined. Since
$A_0(n)=G(0,n)$ is real-valued and $A_1(n)=\frac{i}{4\pi}$, we have $S^*=S$ and $(S_1vA_1vS_1)^*=-S_1vA_1vS_1$. Moreover, $S$ is Fredholm, and $S_1$ is of finite rank. Hence
$\operatorname{Ran}S$ is closed, while
$\operatorname{Ran}(S_1vA_1vS_1)$ is finite-dimensional and therefore
closed. It then follows from Remark \ref{remark of invertibility} that
$D_0$ and $D_1$ are well-defined and satisfy
\begin{equation*}
D_0S_1=S_1=S_1D_0,\qquad D_1S_2=S_2=S_2D_1.
\end{equation*}
It remains to consider $D_2$. Since $S_2\ell^2(\mathbb{Z}^3)$ is
finite-dimensional, it suffices to prove that
$S_2vA_2vS_2$ is injective on $S_2\ell^2(\mathbb{Z}^3)$. Suppose that
$f\in S_2\ell^2(\mathbb{Z}^3)$ satisfies $S_2vA_2vS_2f=0$. Then
$$0=\left<S_2vA_2vS_2f,f\right>=\left<A_2vf,vf\right>.$$
Since $f\in S_2\ell^2(\mathbb{Z}^3)$, we have
$\langle f,v\rangle=0$, and hence $A_1vf=0$. Taking $N=2$ and
$\omega=i\varepsilon$, $\varepsilon>0$, in Lemma
\ref{lemma of R0 0}, we therefore obtain
\begin{align*}
\left<A_2vf,vf\right> &=\Big<\lim\limits_{\varepsilon\rightarrow0}\frac{R_0(i\varepsilon)-A_0-A_1(i\varepsilon)^{\frac{1}{2}}}{i\varepsilon}vf,vf\Big>=\lim\limits_{\varepsilon\rightarrow0} \Big<\frac{R_0(i\varepsilon)-A_0}{i\varepsilon}vf,vf\Big>\\
&=\lim\limits_{\varepsilon\rightarrow0}\int_{(-\pi,\pi]^3}\frac{1}{(\mathcal{M}(x)-i\varepsilon)\mathcal{M}(x)}|(\mathcal{F}(vf))(x)|^2dx\\
&=\big<\mathcal{F}(A_0vf),\mathcal{F} (A_0vf)\big>\\
&=\big<A_0vf,A_0vf\big>.
\end{align*}
Indeed, since $f\in S_2\ell^2(\mathbb Z^3)$, $\langle f,v\rangle=0$ and Lemma \ref{chara of solution and space} (2) gives $A_0vf\in\ell^{2}(\mathbb{Z}^3)$. By the Fourier representation of $A_0(n)$ and Plancherel's theorem,
$\mathcal{F}(vf)(x)/\mathcal{M}(x)=\mathcal{F}(A_0vf)(x)\in L^2((-\pi,\pi]^3)$. Moreover, 
$$\left| \frac{1} {(\mathcal{M}(x)-i\varepsilon)\mathcal{M}(x)} \right| \leq \frac{1}{|\mathcal{M}(x)|^2},$$
so the last limit follows from the dominated convergence theorem. Consequently, $A_0vf=0$. This combined with $Sf=0$ yields $f=0$. Thus
$S_2vA_2vS_2$ is injective on $S_2\ell^2(\mathbb{Z}^3)$ and hence invertible
there. Therefore $D_2$ is well-defined.

Having established the well-definedness of all the operators $D_j$, we now compute the asymptotic expansion of $M^{-1}(\omega)$ in each threshold type.
\vskip0.2cm
{\bf{(1)}} Suppose that {\bf$\bm 0$ is a regular point of $\bm H$}, that is, $S$ is invertible on $\ell^2(\mathbb{Z}^3)$, and assume that {${\beta>3}$}.
Taking $N=0$ in \eqref{expan of R0}, we obtain the following expansion on $\ell^{2}(\mathbb{Z}^3)$:
 \begin{equation*}
M(\omega)=U+vR_0(\omega)v=S+O(\omega^{\frac{1}{2}}),\quad |\omega|\rightarrow 0,\  \arg\omega\in(0,2\pi).
 \end{equation*}
Combining $D_0=S^{-1}$ and Neumann series expansion, we derive 
\begin{equation}\label{inver of M 0 regular}
\bm {M^{-1}(\omega)=D_{0}+D_0O(\omega^{\frac{1}{2}})D_0.}
\end{equation}
\vskip0.1cm
{\bf{(2)}} Suppose that {\bf$\bm 0$ is a resonance of $\bm H$}, i.e., $S$ is not invertible on $\ell^2(\mathbb{Z}^3)$, while $S_1vA_1vS_1$ is invertible on $S_1\ell^2(\mathbb{Z}^3)$, and assume that $\beta>5$. Taking $N=1$ in \eqref{expan of R0}, we obtain
\begin{equation*}
M(\omega)=S+vA_1v\,\omega^{\frac{1}{2}}+O(\omega),\quad |\omega| \rightarrow0,
\end{equation*}
and hence,
\begin{equation}\label{expre M+S_1}
\left(M(\omega)+S_1\right)^{-1}=D_{0}-D_{0}vA_1vD_{0}\,\omega^{\frac{1}{2}}+D_0O(\omega)D_0,\quad |\omega|\rightarrow0.
\end{equation}
Using $S_1D_{0}=S_1=D_{0}S_1$, we have
 \begin{equation*}
    M_1(\omega):=S_1-S_1\big(M(\omega)+S_1\big)^{-1}S_1=\omega^{\frac{1}{2}}\big(S_1vA_1vS_1+S_1O(\omega^{\frac{1}{2}})S_1\big),\quad |\omega|\rightarrow0.
\end{equation*}
By assumption, $M_1(\omega)$ is invertible on $S_1\ell^2(\mathbb{Z}^3)$ and its inverse admits the following expansion:
\begin{equation}\label{expan of M1 1st}
    M^{-1}_1(\omega)=D_{1}\omega^{-\frac{1}{2}}+D_1O(1)D_1,\quad |\omega|\rightarrow0.
\end{equation}
Applying Lemma \ref{lemm of expa} to
$M(\omega)$, we obtain
\begin{equation}\label{rela inver of M and M1}
    M^{-1}(\omega)=(M(\omega)+S_1)^{-1}\big(I+S_1M^{-1}_1(\omega)S_1(M(\omega)+S_1)^{-1}\big).
\end{equation}
Substituting \eqref{expre M+S_1}  and \eqref{expan of M1 1st} into \eqref{rela inver of M and M1}, we derive
\begin{equation}\label{inver of M 0 resonan}
\bm{M^{-1}(\omega)=S_1D_{1}S_1\omega^{-\frac{1}{2}}+O(1).}
\end{equation}
\vskip0.2cm
{\bf{(3)}} Let {\bf$\bm 0$ be an eigenvalue of $\bm H$} and $\beta>7$. Taking $N=2$ in \eqref{expan of R0} and repeating the process as in (2), we further obtain
\begin{equation}\label{M+S_1 eigenv}
    \left({M}(\omega)+S_1\right)^{-1}=D_{0}-D_{0}vA_1vD_{0}\,\omega^{\frac{1}{2}}+\big((D_{0}vA_1v)^2D_{0}-D_{0}vA_2vD_{0}\big)\omega+D_0O(\omega^{\frac{3}{2}})D_0
\end{equation}
and 
\begin{equation*}
    M_1(\omega)=\omega^{\frac{1}{2}}\Big(S_1vA_1vS_1+\big(S_1vA_2vS_1-S_1vA_1vD_{0}vA_1vS_1\big)\omega^{\frac{1}{2}}+S_1O(\omega)S_1\Big)=:\omega^{\frac{1}{2}}\widetilde{M}_1(\omega).
\end{equation*}
Since $S_2\ell^2(\mathbb{Z}^3)={\rm Ker}S_1vA_1vS_1|_{S_1\ell^2(\mathbb{Z}^3)}$, the operator $\widetilde{M}_1(\omega)+S_2$ is invertible on $S_1\ell^2(\mathbb{Z}^3)$ and 
\begin{equation}\label{expre M_1+S_2}
\left(\widetilde{M}_1(\omega)+S_2\right)^{-1}=D_{1}+D_1(S_1vA_1vD_{0}vA_1vS_1-S_1vA_2vS_1)D_1\omega^{\frac{1}{2}}+D_1O(\omega)D_1,\quad |\omega|\rightarrow0.
\end{equation}
Using $S_2D_{j}=S_2=D_{j}S_2\ (j=0,1),\ S_2S_1=S_2=S_1S_2$ together with $  A_1vS_2=0$, we obtain $$M_2(\omega):=S_2-S_2\big(\widetilde{M}_1(\omega)+S_2\big)^{-1}S_2=\omega^{\frac{1}{2}}\Big(S_2vA_2vS_2+S_2O(\omega^\frac{1}{2})S_2\Big).$$ 
Since $S_2vA_2vS_2$ is invertible on $S_2\ell^2(\mathbb{Z}^3)$. It follows that ${M}_2(\omega)$ is invertible on $S_2\ell^2(\mathbb{Z}^3)$ with
\begin{equation}\label{inverse of M2}
M^{-1}_2(\omega)=S_2D_{2}S_2\,\omega^{-\frac{1}{2}}+S_2O(1)S_2,\quad |\omega|\rightarrow0.  
\end{equation}
Applying Lemma \ref{lemm of expa} to
$\widetilde{M}_1(\omega)$, and using \eqref{expre M_1+S_2} and \eqref{inverse of M2}, we get
\begin{equation}\label{rela inver of tutaM1 and M2}
   \widetilde{ M}^{-1}_1(\omega)=(\widetilde{M}_1(\omega)+S_2)^{-1}\Big(I+S_2M^{-1}_2(\omega)S_2(\widetilde{M}_1(\omega)+S_2)^{-1}\Big)=S_2D_2S_2\,\omega^{-\frac{1}{2}}+D_1O(1).
\end{equation}
Therefore,
\begin{equation*}
M^{-1}_1(\omega)=S_2D_{2}S_2\,\omega^{-1}+D_1O(\omega^{-\frac{1}{2}}),\quad |\omega|\rightarrow0.
\end{equation*}
Combining this with \eqref{M+S_1 eigenv} and \eqref{rela inver of M and M1}, gives 
\begin{equation}\label{inver of M 0 eigen}
\bm{M^{-1}(\omega)=S_2D_{2}S_2\,\omega^{-1}+O(\omega^{-\frac{1}{2}}).}
\end{equation}
Hence, substituting \eqref{inver of M 0 regular}, \eqref{inver of M 0 resonan}, \eqref{inver of M 0 eigen} into \eqref{rela betw RV and inver of Mw}, respectively, we obtain the expansions in Proposition \ref{Asymptotic expansion theorem 0}. Moreover, combining the derivative argument for $R_0(\omega)$ in \cite[Remark 2.5]{Kop09} with the corresponding expansions of $M^{-1}(\omega)$ and the resolvent identity \eqref{rela betw RV and inver of Mw}, the above perturbed expansions can be differentiated twice in $\mathcal{B}(\sigma,-\sigma)$ for $\sigma>\frac52$.
\vskip0.1cm
{\bf(4)} Finally, we prove that $\mathcal{P}_0:=A_0vS_2D_{2}S_2vA_0$ is the projection onto the eigenspace of the eigenvalue $\lambda=0$. 
Denote by $V_0$ the eigenspace of the eigenvalue $0$ of $H$, that is,
$V_0:=\{\phi\in\ell^2(\mathbb{Z}^3):H\phi=0\}.
$ Let $\{f_j\}^{N}_{j=1}$ be an orthonormal basis  of $S_2\ell^2(\mathbb{Z}^3)$. For each $j\in\{1,2,\cdots, N\}$, define $\phi_j:=-A_0vf_j$. By Lemma \ref{chara of solution and space} (ii), $\phi_j\in V_0$ and $f_j=Uv\phi_j$. Moreover, since $\{f_j\}^{N}_{j=1}$ is linearly independent, $\{\phi_j\}^{N}_{j=1}$ is a basis of the set $V_0$. We claim that 
\begin{equation}\label{projection p0}
\mathcal{P}^2_0=\mathcal{P}_0,\quad \mathcal{P}^*_0=\mathcal{P}_0,\quad \mathcal{P}_0\ell^2(\mathbb{Z}^3)=V_0,
\end{equation}
which yields the desired result. 

To this end, let $A:=(a_{mj})_{N\times N}$ be the matrix of $S_2vA_2vS_2$ with respect to the orthonormal basis $\{f_j\}^{N}_{j=1}$ of $S_2\ell^2(\mathbb{Z}^3)$, where
\begin{equation*}
a_{mj}=\left<S_2vA_2vS_2f_m,f_j\right>=\left<A_2vf_m,vf_j\right>=\left<A_0vf_m,A_0vf_j\right>=\left<\phi_m,\phi_j\right>.
\end{equation*}
For any $g\in\ell^2(\mathbb{Z}^3)$, we  compute
\begin{equation*}
\mathcal{P}_0g=A_0vS_2D_{2}S_2vA_0g=-\sum\limits_{j=1}^{N}\left<g,\phi_j\right>A_0vS_2D_{2}f_j=\sum\limits_{k,j=1}^{N}\left<g,\phi_j\right>b_{jk}\phi_k,
\end{equation*}
where $b_{jk}$ is the $(j,k)$ element of the inverse matrix $A^{-1}$ of $A$. Particularly, note that 
$$\mathcal{P}_0\phi_m=\sum\limits_{k=1}^{N}\sum\limits_{j=1}^{N}a_{mj}b_{jk}\phi_k=\sum\limits_{k=1}^{N}(AA^{-1})_{mk}\phi_k=\phi_m,$$
which establishes \eqref{projection p0} and thus, we complete the proof.

{\bf\underline{(i)}} ``$\bm{\Longrightarrow}$" Given $f\in S_1{\ell^2(\mathbb{Z}^3)}$, then
$(U+vA_0v)f=Sf=0.$
Multiplying both sides by $U$, it then yields that 
$f=-UvA_0vf$. Define $\phi:=-A_0vf$. Then $f=Uv\phi$ and hence $vf=V\phi$. Since $-\Delta A_0=\delta_0$, it follows that
$H\phi=(-\Delta+V)\phi=\Delta A_0vf+V\phi=-vf+vf=0.$
Let 
$$W:=\bigcap\limits_{s>1/2} \ell^{2, -s}(\mathbb{Z}^3).$$
To show that $\phi\in W$, it suffices to study the behavior of $\phi(n)$ for large $|n|$. Recall from Remark \ref{remark of free expan} (3) that  $A_0(n)=G(0,n)$. Assume that $|n|\geqslant5$. We decompose $(A_0vf)(n)$ as
\begin{align}
-\phi(n)&=(A_0vf)(n)=\sum\limits_{m}^{}G(0,n-m)v(m)f(m)\notag\\
=&\sum\limits_{m\neq n}^{}(G(0,n-m)-G_d(n-m))v(m)f(m)+\sum\limits_{m\neq n}^{}G_d(n-m)v(m)f(m)+G(0,0)v(n)f(n)\notag\\
=&:\Phi_1(n)+\Phi_2(n)+\Phi_3(n).\label{A0vf in S1}
\end{align}
Clearly, 
$|\Phi_3(n)|\lesssim\left<n\right>^{-\frac{\beta}{2}}\in W$ if $\beta>2$. Moreover, let $\mathbf{1}_{\{n\neq0\}}(n)$ be the characteristic function on the set $\{n\neq0\}$. By \eqref{relation of phi0 and g0}, we have
\begin{equation*}
    |\Phi_1(n)|\lesssim (\varphi*\left|vf\right|)(n),\quad \varphi(n)=\mathbf{1}_{\{n\neq0\}}(n)|n|^{-3}.
\end{equation*}
Since $vf\in\ell^1(\mathbb{Z}^3)$ for $\beta>3$ and $\varphi(n)\in\ell^2(\mathbb{Z}^3)$, Young's inequality gives
\begin{equation}\label{A}
\Phi_1(n)\in\ell^2(\mathbb{Z}^3)\subseteq W.
\end{equation}
For $\Phi_2(n)$, we divide it into the following three parts
\begin{align*}
\Phi_2(n)=\frac{1}{4\pi}\sum\limits_{m\neq n}^{}\frac{1}{|n-m|} v(m)f(m)=\frac{1}{4\pi}\sum\limits_{j=1}^{3}\sum\limits_{m\in R_j}\frac{1}{|n-m|} v(m)f(m)=:\frac{1}{4\pi}\sum\limits_{j=1}^{3}\Phi_{2j}(n),
\end{align*}
where $R_1=\{m\mid|m-n|=1\}$ and 
\begin{equation*}
   R_2=\{m\mid |m-n|>1,|m|\geqslant\frac{|n|}{2}\},\quad R_3=\{m\mid|m-n|>1,|m|<\frac{|n|}{2}\}.
\end{equation*}
For $\Phi_{21}(n)$, since $\left<m\right>\approx\left<n\right>$ for any $m\in R_1$, we obtain, for $\beta>5$,  
\begin{equation}\label{Phi21}
|\Phi_{21}(n)|\lesssim\left<n\right>^{-1}\sum\limits_{m\in R_1}\left<m\right>^{-\frac{\beta}{2}+1}|f(m)|\lesssim\left<n\right>^{-1}.
\end{equation}
For $\Phi_{22}(n)$, the Cauchy--Schwarz inequality and $\left<m\right>\gtrsim\left<n\right>$ for any $m\in R_2$ yield
 \begin{align}
    |\Phi_{22}(n)|^2&\lesssim \sum\limits_{m\in R_2}|n-m|^{-2}\left<m\right>^{-\beta}\lesssim\sum\limits_{1<|n-m|\leq |n|/4}\left<n\right>^{-\beta}+\sum\limits_{\substack{m\in R_2\\ |n-m|>|n|/4}}\left<n\right>^{-2}|m|^{-\beta}\notag\\
    &\lesssim\left<n\right>^{3-\beta}+\left<n\right>^{-2}\lesssim \left<n\right>^{-2}~({\rm since}\ \beta>5).\label{Phi22}
 \end{align} 
Finally, if $m \in R_3$, then
$|m-n| \approx |n|$. Hence, 
\begin{equation*}
|\Phi_{23}(n)|\lesssim \left<n\right>^{-1}\sum\limits_{m\in R_3}^{}|v(m)||f(m)|\lesssim \left<n\right>^{-1}.
\end{equation*}
Combining this with \eqref{Phi21} and \eqref{Phi22}, we conclude that $|\Phi_2(n)|\lesssim\left<n\right>^{-1}\in W $ and $\phi\in W$ follows.
\vskip0.2cm
``$\bm{\Longleftarrow}$" Conversely, suppose that there exists $\phi\in W$ satisfying the equation $H\phi=0$.
 Let $f=Uv\phi$. We will show that $\phi(n)=-(A_0vf)(n)$. Once this identity is established, it follows that
$$Sf=(U+vA_0v)f=v\phi-v\phi=0,$$
and hence $f\in S_1\ell^2(\mathbb{Z}^3)$. Indeed, since $H\phi=0$, we have $\Delta\phi=V\phi=vf=\Delta(-A_0vf).$
Moreover, by the argument in {\bf\underline{(i)~``$\bm{\Longrightarrow}$"}}, we have $A_0vf\in W$. In other words, the equation $\Delta(\phi+A_0vf)=0$ has solution in 
 $W$. By the uniqueness of solutions in $W$, it follows that $\phi=-A_0vf$.
\vskip0.2cm
{\bf{\underline{(ii)}}}~``$\bm{\Longrightarrow}$" Assume that $f\in S_{2}\ell^2(\mathbb{Z}^3)$, i.e., $f\in S_{1}\ell^2(\mathbb{Z}^3) $ and $\left<f,v\right>=0$. Then by part {\bf{\underline{(i)}}}, $\exists~\phi(n)=-(A_0vf)(n)\in W$ such that $H\phi=0$. We claim that $\phi \in\ell^2(\mathbb{Z}^3).$
In fact, for $|n|\geq5$, using $\left<f,v\right>=0$, we have 
\begin{equation}
\begin{split}
-\phi(n)&=(A_0vf)(n)=\sum\limits_{m}^{}\big(G(0,n-m)-(4\pi|n|)^{-1})v(m)f(m)\\
&=\Phi_1(n)+\sum\limits_{m\neq n}^{}\frac{|n|-|n-m|}{4\pi|n-m|\cdot |n|}v(m)f(m)+(G(0,0)-(4\pi|n|)^{-1})v(n)f(n)\\
&=:\Phi_1(n)+\widetilde{\Phi}_2(n)+\widetilde{\Phi}_3(n),
\end{split}
\end{equation}
where $\Phi_1(n)\in \ell^2(\mathbb{Z}^3)$ is defined in \eqref{A0vf in S1}. It is clear that $|\widetilde{\Phi}_3(n)|\lesssim \left<n\right>^{-\frac{\beta}{2}}\in \ell^2(\mathbb{Z}^3)$ if $\beta>3$.
As for $\widetilde{\Phi}_2(n)$, we note that
\begin{equation*}
    |\widetilde{\Phi}_2(n)|\lesssim \left<n\right>^{-1}\sum\limits_{m\neq n}\frac{1}{|n-m|}\left<m\right>^{-\frac{\beta-2}{2}}|f(m)|.
\end{equation*}
Since $\beta>7$, applying the same argument used for $\Phi_2(n)$ to the latter sum, we obtain $|\widetilde{\Phi}_2(n)|\lesssim\left<n\right>^{-2}\in \ell^2(\mathbb{Z}^3)$. Therefore, $\phi\in\ell^2(\mathbb{Z}^3)$.
\vskip0.3cm
``$\bm{\Longleftarrow}$" Suppose there exists $\phi\in \ell^2(\mathbb{Z}^3)$ such that $H\phi=0$. Let $f=Uv\phi$. Since $\ell^2(\mathbb{Z}^3)\subseteq W,$ it follows from part {\bf{\underline{(i)``$\bm{\Longleftarrow}$"}}} that $f\in S_1\ell^2(\mathbb{Z}^3)$ and
$\phi(n)=-(A_0vf)(n)$. It remains to show $\left<f,v\right>=0$, which will yield $f\in S_2\ell^2(\mathbb{Z}^3)$.
To this end, for any $\delta>0$, we introduce
$$F(\delta)=\sum_{n\in\mathbb{Z}^3}V(n)\phi(n)\eta(\delta n),$$
where $\eta(x)\in C^{\infty}_0(\mathbb{R}^3)$ satisfies $\eta(x)=1$ for $|x|\leqslant1$ and $\eta(x)=0$ for $|x|>2$. On the one hand, by the assumptions on $V$ and $\phi\in \ell^2(\mathbb{Z}^3)$, Lebesgue's dominated convergence theorem yields
$$\left<f,v\right>=\left<\phi,V\right>=\lim_{\delta\rightarrow0}F(\delta).$$
On the other hand, for any $\delta>0$, using $V\phi=\Delta \phi$ and the self-adjointness of $\Delta$, we get
\begin{equation*}
    F(\delta)=\sum_{n\in\mathbb{Z}^3}(\Delta \phi)(n)\eta(\delta n)=\sum_{n\in\mathbb{Z}^3}\phi(n)(\Delta G_{\delta})(n),
\end{equation*}
where $G_{\delta}(x)=\eta(\delta x)$. Applying the differential mean value theorem to $\Delta G_{\delta}$, we obtain
\begin{equation*}
 (\Delta G_{\delta})(n)=\delta^2\sum\limits_{j=1} ^{3}(\partial^2_j\eta)\big(\delta(n+(\Theta_j-1)e_j)\big), \quad \Theta_j\in[0,2].
 \end{equation*}
Restricting $0<\delta<1$, using  supp $\eta\subseteq\{|x|\leq2\}$ and uniform boundedness of $\partial^2_j\eta$, we further derive
 \begin{equation*}
 \|\Delta G_{\delta}\|^2_{\ell^2(\mathbb{Z}^3)}\lesssim \delta^4\sum\limits_{|n|\leqslant\frac{3}{\delta}}^{}\lesssim \delta.
 \end{equation*}
 Using $\phi\in\ell^2(\mathbb{Z}^3)$ and H\"{o}lder's inequality, we conclude $\lim\limits_{\delta\rightarrow0}F(\delta)=0$. This completes the proof.

\label{Asymptotic expansion theorem 4}
 Let $H=-\Delta+V$ with $|V(n)|\lesssim \left<n\right>^{-\beta}$ for some $\beta>0$. Then the following asymptotic expansions hold in $\mathcal{B}(\sigma,-\sigma)$ as $|\omega|\rightarrow0$ with $\pm\operatorname{Im}\omega>0$.  
\begin{itemize}
\item[{\rm(1)}] If $4$ {\rm(}resp. $8${\rm)} is a regular point of $H$ and $\beta>7$, then for any $\sigma>\frac{7}{2}$, 
\begin{align*}                               
\begin{split}
R^{\pm}_V(4+\omega)&=E^{\pm}_0-E^{\pm}_0vF^{\pm}_0vE^{\pm}_0+(B^{\pm}_0+E^{\pm}_0vF^{\pm}_0vB^{\pm}_0vF^{\pm}_0vE^{\pm}_0-B^{\pm}_0vF^{\pm}_0vE^{\pm}_0-E^{\pm}_0vF^{\pm}_0vB^{\pm}_0)\omega^{\frac{1}{2}}+O(\omega),\\
    R^{\pm}_V(8-\omega)&=\mathcal{E}^{\pm}_0-\mathcal{E}^{\pm}_0v\mathcal{F}^{\pm}_0v\mathcal{E}^{\pm}_0+(\mathcal{B}^{\pm}_0+\mathcal{E}^{\pm}_0v\mathcal{F}^{\pm}_0v\mathcal{B}^{\pm}_0v\mathcal{F}^{\pm}_0v\mathcal{E}^{\pm}_0-\mathcal{B}^{\pm}_0v\mathcal{F}^{\pm}_0v\mathcal{E}^{\pm}_0-\mathcal{E}^{\pm}_0v\mathcal{F}^{\pm}_0v\mathcal{B}^{\pm}_0)\omega^{\frac{1}{2}}+O(\omega).
    \end{split}
\end{align*}
\item [{\rm(2)}] If $4$ {\rm(}resp. $8${\rm)} is an eigenvalue of $H$ and $\beta>11$, then for any $\sigma>\frac{11}{2}$,
\begin{align*}                               
R^{\pm}_V(4+\omega)=-E^{\pm}_0vQ^{\pm}_2F^{\pm}_2Q^{\pm}_2vE^{\pm}_0\omega^{-1}+O(\omega^{-\frac{1}{2}}),\quad  R^{\pm}_V(8-\omega)=-\mathcal{E}^{\pm}_0v\mathcal{Q}^{\pm}_2\mathcal{F}^{\pm}_2\mathcal{Q}^{\pm}_2v\mathcal{E}^{\pm}_0\omega^{-1}+O(\omega^{-\frac{1}{2}}).
\end{align*}
\end{itemize}
Here  
\begin{align*}
F^{\pm}_{0}&=(Q^{\pm}+Q^{\pm}_1)^{-1},\quad \mathcal{F}^{\pm}_{0}=(\mathcal{Q}^{\pm}+\mathcal{Q}^{\pm}_1)^{-1},\\
F^{\pm}_2&=(Q^{\pm}_2vE^{\pm}_1vQ^{\pm}_2)^{-1}\ {\rm on}\ Q^{\pm}_2\ell^2(\mathbb{Z}^3),\quad \mathcal{F}^{\pm}_2=(\mathcal{Q}^{\pm}_2v\mathcal{E}^{\pm}_1v\mathcal{Q}^{\pm}_2)^{-1}\ {\rm on}\ \mathcal{Q}^{\pm}_2\ell^2(\mathbb{Z}^3),
\end{align*}
and  $E^{\pm}_0vQ^{\pm}_2F^{\pm}_2Q^{\pm}_2vE^{\pm}_0$ and $-\mathcal{E}^{\pm}_0v\mathcal{Q}^{\pm}_2\mathcal{F}^{\pm}_2\mathcal{Q}^{\pm}_2v\mathcal{E}^{\pm}_0$ are the orthogonal projections onto the eigenspaces of $H$ at $4$ and $8$, respectively. Moreover, these expansions are twice differentiable in $\mathcal{B}(\sigma,-\sigma)$ with $\sigma>\frac{11}{2}$.

\label{Taira lemma}
{\rm (\cite[Theorem 1.7, Lemmas 3.6, 3.7 and Remark 3.8]{NT20})} Let $H=-\Delta+V$ on $\mathbb{Z}^3$ with a real-valued potential $V$ satisfying $|V(n)|\lesssim\langle n\rangle^{-\beta}$ for some $\beta>0$. Let $\lambda\in\{4,8\}$. Then the following statements hold.

{\rm (1)} Let $\beta>7/2$. If $\phi\in\ell^{2,-1}(\mathbb{Z}^3)$ satisfies $\phi+(-\Delta-\lambda\mp i0)^{-1}V\phi=0$, then 
$\phi\in\ell^2(\mathbb{Z}^3)$ and
$\mathcal{F}(V\phi)|_{\mathcal{M}_{\lambda}}=0$, where
\begin{equation*}
    \mathcal{M}_{\lambda}=\{x\in \mathbb{T}^3\mid \mathcal{M}(x)=\lambda\}.
\end{equation*}

{\rm(2)} Let $f\in C^1(\mathbb{T}^3)$ such that $f|_{\mathcal{M}_{\lambda}}=0$. Then, we have $(\mathcal{M}(x)-\lambda\mp i0)^{-1}f=(\mathcal{M}(x)-\lambda)^{-1}f\in L^2(\mathbb{T}^3)$.

\label{chara of solution and space 4}
{\rm Let $H=-\Delta+V$ with $|V(n)|\lesssim \left<n\right>^{-\beta}$ for $\beta>7$. Then
\begin{itemize}
\item [{\rm(i)}]
$f^{\pm}\in Q^{\pm}_1\ell^2(\mathbb{Z}^3)\Longleftrightarrow \exists\ \phi^{\pm}\in \ell^{2,-1}(\mathbb{Z}^3)$ such that $\phi^{\pm}+(-\Delta-4\mp i0)^{-1}V\phi^{\pm}=0$. Moreover, $f^{\pm}=Uv\phi^{\pm}$ and $\phi^{\pm}=-E^{\pm}_0vf^{\pm}$.
\item [{\rm(ii)}] $Q^+_1\ell^2(\mathbb{Z}^3)=Q^-_1\ell^2(\mathbb{Z}^3)$.
\end{itemize}
}

\label{LAP-theorem}
    { Let $H=-\Delta+V$ with $|V(n)|\lesssim \left<n\right>^{-\beta}$ for some $\beta>2$ and $\mathcal{I}=(0,4)\cup(4,8)\cup(8,12)$. Let $[\beta]$ denote the greatest integer not exceeding $\beta$. Then the following statements hold.}
\begin{itemize}
{
\item [{\rm(i)}] The point spectrum $\sigma_p(H)\cap\mathcal{I}$ is discrete, each eigenvalue has finite multiplicity, and the singular continuous spectrum $\sigma_{sc}(H)=\varnothing$.
\vskip0.2cm
\item [{\rm(ii)}] Let $j\in\left\{0,\cdots,[\beta]-2\right\}$ and $\sigma>j+\frac{1}{2}$. Then the norm limits
\begin{equation}\label{boundary value}
   \frac{d^{j}}{d\lambda^j}(\mathcal{R}^{\pm}_V(\lambda))=\lim\limits_{\varepsilon\downarrow0}R^{(j)}_V(\lambda\pm i\varepsilon) \quad {\rm in} \quad \mathcal{B}(\sigma,-\sigma)
    \end{equation}
exist and are norm-continuous on $\mathcal{I}\setminus\sigma_p(H)$, where $R^{(j)}_{V}(\omega)$ denotes the $j$-th derivative of $R_{V}(\omega)$.
    }
\end{itemize}

\label{theorem of estimate of Ij}
{\rm Under the assumptions on $H$ and $V$ in Theorem \ref{decay theorem}, the following decay estimates hold.
\vskip0.1cm
{\bf(1) Estimates for $\mathcal{G}(t)$.}
\vskip0.1cm
For any $\sigma>\frac{5}{2}$, we have
$\|\mathcal{G}(t)\|_{\mathcal{B}(\sigma, -\sigma)} = O(t^{-2})$ as $t\rightarrow+\infty$.
\vskip0.2cm
{\bf(2) Estimates for $\mathcal{D}_0(t)$ and $\mathcal{D}_3(t)$.} For $k=0,3$, 
\begin{equation*}
    \|\mathcal{D}_{k}(t)\|_{\mathcal{B}(\sigma,-\sigma)}=\begin{cases}
        O(t^{-\frac{3}{2}}),&4k~\text{is a regular point of}~ H\\
        O(t^{-\frac{1}{2}}),&4k~\text{is a resonance or an eigenvalue of}~ H
    \end{cases},\quad t\rightarrow+
\infty,
\end{equation*}
where $\sigma>5/2$ in the regular and resonance cases, and $\sigma>7/2$ in the eigenvalue case. 
\vskip0.2cm
{\bf(3) Estimates for $\mathcal{D}_1(t)$ and $\mathcal{D}_2(t)$.} For $k=1,2$ and $\sigma>11/2$, 
\begin{equation*}
\|\mathcal{D}_k(t)\|_{\mathcal{B}(\sigma,-\sigma)}=\begin{cases}
        O(t^{-\frac{3}{2}}),&4k~\text{is a regular point of}~ H\\
        O(t^{-\frac{1}{2}}),&4k~~\text{is an eigenvalue of}~ H
    \end{cases},\quad t\rightarrow+\infty.
\end{equation*}
}

\label{decay rate lemma}
Let $0<\delta\ll1$ and $\alpha\in(-1,1)$. Suppose that $F\in C^{2}((0,\delta],\mathbb{C})$ satisfies \begin{equation}\label{condi for F}
    F(\delta)=0=F'(\delta),\quad F^{(k)}(\lambda)= O(\lambda^{\alpha-k}),\quad\lambda\in(0,\delta],\quad k=0,1,2.
\end{equation} 
Then
\begin{equation*}
\int_{0}^{\delta}e^{-it\lambda}F(\lambda)d\lambda
=O(t^{-(1+\alpha)}),\quad t\rightarrow+\infty.
\end{equation*}

{\bf (1)} Recall from \eqref{gt and Dkt} and supp $ \xi_2\subseteq[\delta,4-\delta]$ that
\begin{equation*}
\mathcal{G}(t)=\sum\limits_{k=1}^3e^{-4kit}\int_{\delta}^{4-\delta}e^{it\lambda}\xi_2(\lambda)\mathcal{R}(4k-\lambda)d\lambda,\quad \xi_2\in C^{\infty}((0,4)).
\end{equation*}
By Lemma \ref{LAP-theorem}, $\mathcal{R}(4k-\lambda)\in C^{2}([\delta,4-\delta],\mathcal{B}(\sigma,-\sigma))$ for $\sigma>\frac{5}{2}$. Moreover, the support condition on $\xi_2$ implies $\xi_2(\delta)=\xi_2(4-\delta)
=
\xi_2'(\delta)=\xi_2'(4-\delta)=0$. Integrating by parts twice in the inner integral of $\mathcal{G}(t)$ then gives $$\|\mathcal{G}(t)\|_{\mathcal{B}(\sigma, -\sigma)} = O(t^{-2}),\quad t\rightarrow+\infty.$$
\vskip0.2cm
{\bf (2)} From \eqref{gt and Dkt} and supp $\xi^{\pm}_1(\lambda)\subseteq(0,2\delta]$, we have
\begin{equation*}
\mathcal{D}_0(t)=\int_{0}^{2\delta}e^{-it\lambda}\xi^+_1(\lambda)\mathcal{R}(\lambda)d\lambda,\quad \mathcal{D}_3(t)=e^{-12it}\int_0^{2\delta} e^{it\lambda}\xi^-_1(\lambda)\mathcal{R}(12-\lambda)d\lambda.
\end{equation*}
It suffices to consider $\mathcal{D}_0(t)$, since the argument for
$\mathcal{D}_3(t)$ is analogous. Combining Lemma \ref{LAP-theorem} with
Theorem \ref{Asymptotic expansion theorem_0}, we obtain, for
$j=0,1,2$ and $0<\lambda\leq2\delta$,
\begin{equation*}
\|\mathcal{R}^{(j)}(\lambda)\|_{\mathcal{B}(\sigma,-\sigma)}=\begin{cases}
    O(\lambda^{\frac{1}{2}-j}),&0~\  is\ a\ regular\ point\ of\ H\\
    O(\lambda^{-\frac{1}{2}-j}),&0~\ is\ a\ resonance\ or\ an\ eigenvalue\ of\ H
\end{cases}
\end{equation*}
where $\sigma>\frac52$ in the regular and resonance cases and
$\sigma>\frac72$ in the eigenvalue case.
Applying Lemma \ref{decay rate lemma} to $\xi^+_1(\lambda)\mathcal{R}(\lambda)$, we derive the desired estimates.
\vskip0.2cm
{\bf(3)} We only deal with $\mathcal{D}_1(t)$, since the case of $\mathcal{D}_2(t)$ is similar. Suppose first that  4 is a regular point of $H$. Combining Lemma \ref{LAP-theorem} with Theorem \ref{Asymptotic expansion theorem_4}, we obtain, for $0<\lambda\leq 2\delta$, 
\begin{equation*}
    \mathcal{R}(4\pm\lambda)=
        \frac{1}{2\pi i}(\mathbb{B}^+_0-\mathbb{B}^-_0)+\widetilde{\mathcal{R}}_{\pm}(\lambda),
\end{equation*}
where $\widetilde{\mathcal{R}}_{\pm}(\lambda)$ satisfies
\begin{equation*}
\|\widetilde{\mathcal{R}}^{(j)}_{\pm}(\lambda)\|_{\mathcal{B}(\sigma,-\sigma)}=
    O(\lambda^{\frac{1}{2}-j}),\quad j=0,1,2,\quad \sigma>7/2.
\end{equation*}
Then 
\begin{align*}
\mathcal{D}_1(t)&=\sum\limits_{\pm}\int_{0}^4e^{-it(4\pm\lambda)}\xi^{\pm}_1(\lambda)\mathcal{R}(4\pm\lambda)d\lambda\\
&=\frac{e^{-4it}}{2\pi i}(\mathbb{B}^+_0-\mathbb{B}^-_0)\sum\limits_{\pm}\int_{0}^4e^{\mp it\lambda}\xi^{\pm}_1(\lambda)d\lambda+\sum\limits_{\pm}\int_{0}^4e^{-it(4\pm\lambda)}\xi^{\pm}_1(\lambda)\widetilde{\mathcal{R}}_{\pm}(\lambda)d\lambda,\\
&=:\mathcal{D}_{11}(t)+\mathcal{D}_{12}(t).
\end{align*}
Since $\xi^{\pm}_1(4)=0$ and $\xi^{\pm}_1(0)=1$, integration by parts gives 
\begin{equation*}
    \int_{0}^4e^{\mp it\lambda}\xi^{\pm}_1(\lambda)d\lambda=\frac{\mp i}{t}+\frac{\mp i}{t}\int_{0}^{4}e^{\mp it\lambda}\big(\xi^{\pm}_1\big)^{'}(\lambda)d\lambda=\frac{\mp i}{t}+O(t^{-2}),\quad t\rightarrow+\infty.
\end{equation*}
 The leading $t^{-1}$ terms cancel after summing over ``$\pm$", and hence
$$\|\mathcal{D}_{11}(t)\|_{\mathcal{B}(\sigma,-\sigma)}=O(t^{-2}),\quad t\rightarrow +\infty,\quad \sigma>7/2.$$
On the other hand, applying Lemma \ref{decay rate lemma} to $\xi^{\pm}_1(\lambda)\widetilde{\mathcal{R}}_{\pm}(\lambda)$ yields  
$$\|\mathcal{D}_{12}(t)\|_{\mathcal{B}(\sigma,-\sigma)}=O(t^{-3/2}),\quad t\rightarrow +\infty,\quad \sigma >7/2.$$
Therefore, when $4$ is a regular point of $H$ and 
$\sigma>7/2$,
\begin{equation*} \|\mathcal{D}_1(t)\|_{\mathcal{B}(\sigma,-\sigma)}=
O(t^{-3/2}),\quad t\rightarrow+\infty.
\end{equation*}

Suppose now that $4$ is an eigenvalue of $H$. Combining Lemma \ref{LAP-theorem} with Theorem \ref{Asymptotic expansion theorem_4}, we obtain 
\begin{equation*}
\|{\mathcal{R}}^{(j)}(4\pm\lambda)\|_{\mathcal{B}(\sigma,-\sigma)}=
    O(\lambda^{-\frac{1}{2}-j}),\quad j=0,1,2,\quad \sigma>11/2.
\end{equation*}
Using Lemma \ref{decay rate lemma}, we have \begin{equation*} \|\mathcal{D}_1(t)\|_{\mathcal{B}(\sigma,-\sigma)}=
O(t^{-1/2}),\quad t\rightarrow+\infty,\quad \sigma>11/2.
\end{equation*} 
Hence, we complete the proof.

For sufficiently large $t$, we have $t^{-1}<\delta$. We split the integral as
\begin{equation*}
\int_{0}^{\delta} e^{-it\lambda} F(\lambda) d\lambda=\Big(\int_{0}^{\frac{1}{t}} +\int_{\frac{1}{t}}^{\delta} \Big)e^{-it\lambda} F(\lambda) d\lambda =:I_1(t)+I_2(t).
\end{equation*}
 Since $F(\lambda)=O(\lambda^{\alpha})$ on $(0,\delta\,]$ and $\alpha>-1$, we have $|I_1(t)|\lesssim t^{-(\alpha+1)}$. We next estimate $I_2(t)$. Integrating by parts and using $F(\delta)=0$ together with $F(t^{-1})=O(t^{-\alpha})$, we obtain
\begin{equation*}
\begin{split}
    I_2(t)=\frac{e^{-i}}{it}F(t^{-1}) +\frac{1}{it}\int_{\frac{1}{t}}^{\delta}e^{-it\lambda}F^{'}(\lambda)d\lambda
    &=O(t^{-(1+\alpha)})+\frac{1}{it}\int_{\frac{1}{t}}^{\delta}e^{-it\lambda}F^{'}(\lambda)d\lambda.
\end{split}
\end{equation*}
For the second integral,  suppose first that $-1<\alpha<0$. Using $F'(\lambda)=O(\lambda^{\alpha-1})$, we obtain
\begin{equation*}
    \Big|\frac{1}{it}\int_{\frac{1}{t}}^{\delta}e^{-it\lambda}F^{'}(\lambda)d\lambda\Big|\lesssim \frac{1}{t}\int_{\frac{1}{t}}^{\delta}\lambda^{\alpha-1} d\lambda=\frac{1}{\alpha t}(\delta^{\alpha}-t^{-\alpha})\leq \frac{-1}{\alpha}t^{-(1+\alpha)}.
\end{equation*}
When $0\leq\alpha<1$, integrating by parts once more and using $F'(\delta)=0$, we derive 
\begin{equation*}
    \Big|\frac{1}{it}\int_{\frac{1}{t}}^{\delta}e^{-it\lambda}F^{'}(\lambda)d\lambda\Big|=\frac{1}{t^2}\Big|-e^{-i}F'(t^{-1})-\int_{\frac{1}{t}}^{\delta}e^{-it\lambda}F^{''}(\lambda)d\lambda\Big|\lesssim \frac{1}{t^2}\Big(t^{1-\alpha}+\int_{\frac{1}{t}}^{\delta}\lambda^{\alpha-2} d\lambda\Big)\lesssim t^{-1-\alpha}.
\end{equation*}
Thus $|I_2(t)|\lesssim t^{-(1+\alpha)}$, and the desired estimate follows.

\label{coarea formula lemma}
{\rm (\cite[Lemma 3.1]{NT20})} For $\psi\in C(\mathbb{T}^3)$, we have
\begin{equation*}
    \int_{\mathbb{T}^3}\psi(\xi)d\xi=\int_{0}^{12}\int_{\mathcal{M}_{\lambda}}\psi(\xi)\frac{d\sigma_\lambda(\xi)}{|\nabla\mathcal{M}(\xi)|}d\lambda, 
\end{equation*}
where 
$\mathcal{M}_{\lambda}=\{\xi\in \mathbb{T}^3\mid\mathcal{M}(\xi)=\lambda\}$ and $d\sigma_{\lambda}(\xi)$ denotes the induced surface measure of $\mathcal{M}_{\lambda}$.

Let \begin{equation}\label{Sigma4}
      \Sigma_4:=\{x\in \mathcal{M}_4\mid(\nabla\mathcal{M})(x)=0\}.
  \end{equation}
Fix $x_0=(x^{(1)}_0,x^{(2)}_0,x^{(3)}_0)\in \mathcal{M}_4\setminus\Sigma_4.$ Without loss of generality, assume that $(\partial^{}_{x_3}\mathcal{M})(x_0)\neq0$. We introduce the local coordinate $t=\mathcal{M}(x)-4$. Let $y=(x_1,x_2)$, $y_0=(x^{(1)}_0,x^{(2)}_0)$ and define  $$G(t,y,x_3):=\mathcal{M}(y,x_3)-4-t,\quad t\in \mathbb{R}, \quad y\in \mathbb{R}^2,\quad x_3\in\mathbb{R}.$$
Then 
 $$
G(0,y_0,x^{(3)}_0)=0,\qquad (\partial^{}_{x_3}G)(0,y_0,x^{(3)}_0)=(\partial^{}_{x_3}\mathcal{M})(x_0)\neq0.
$$
By the implicit function theorem, there exist neighborhoods $I$ of $0$ and $D(y_0)$ of $y_0$, together with a unique function $\psi(t,y)\in C^{\infty}(I\times D(y_0))$, such that $\psi(0,y_0)=x^{(3)}_0$ 
 and $x_3=\psi(t,y)$. Then 
 $$x=(y,\psi(t,y))=:\Psi(t,y)\in \Psi(I\times D(y_0)).$$

 Since $(\partial^{}_{x_3}\mathcal{M})(x_0)\neq0$, there exists $(-\delta,\delta)\times D\subseteq I\times D(y_0)$ such that $x_0\in U:=\Psi((-\delta,\delta)\times D)$ and $\nabla\mathcal{M}(x)\neq0$ for $x\in U$. Choose $\rho\in C^{\infty}_0((-\delta,\delta))$ with $\rho(0)=1$ and $0\not\equiv b(y)\in C^{\infty}_0(D)$. Let $a(\Psi(t,y))=\rho(t)b(y).$ Then $a\in C^{\infty}_0(U)$ and  $a|_{\mathcal{M}_4}=b(y)\not\equiv 0$. We define the distribution $\mathcal{F}\phi$ on $\mathbb{T}^3$ by  
\begin{equation}\label{Fphi expre as M4}
   (\mathcal{F}\phi)(\varphi)=\int_{\mathcal{M}_4}a(\xi)\varphi(\xi)\frac{d\sigma_{4}(\xi)}{|\nabla\mathcal{M}(\xi)|},\qquad \varphi\in C^{\infty}(\mathbb{T}^3).  
\end{equation}
This is well defined since $\operatorname{supp}a\subseteq U$ and $\nabla\mathcal{M}\neq0$ on $U$. Moreover,  $\mathcal{F}\phi\neq0$ and $(\Delta+4)\phi=0$ since 
$$(\mathcal{F}\phi)(\overline{a})>0,\qquad(\mathcal{M}(\cdot)-4)(\mathcal{F}\phi)(\varphi)=(\mathcal{F}\phi)((\mathcal{M}(\cdot)-4)\varphi(\cdot))=0.$$ 

It remains to show that $\phi\in \ell^{2,-1}(\mathbb{Z}^3)$, or equivalently, $\mathcal{F}\phi\in H^{-1}(\mathbb{T}^3)$. In the local coordinates $\xi=\Psi(t,y)$, we write $d\xi=J(t,y)dtdy$, where $J$ is the Jacobian. Then for any $\varphi(\xi)\in C^{\infty}_0(U)$, by Lemma \ref{coarea formula lemma},
\begin{equation*}
 (\mathcal{F}\phi)(\varphi)=\int_{D}a(\Psi(0,y))J(0,y)\varphi(\Psi(0,y))dy=:\int_{D}\widetilde{a}(y)\widetilde{\varphi}(0,y)dy,
\end{equation*}
where $\widetilde{a}(y)=a(\Psi(0,y))J(0,y)$ and $\widetilde{\varphi}(t,y)=\varphi(\Psi(t,y))$. Thus, under the smooth coordinate map $\Psi$, the distribution $\mathcal{F}\phi$ corresponds locally to $$W(t,y)=\widetilde{a}(y)\delta_0(t).$$
It suffices to prove $\widetilde{a}(y)\delta_0(t)\in H^{-1}(\mathbb{R}^3)$. Indeed, taking the Fourier transform $\mathcal{F}_c$ on $\mathbb{R}^3$, we obtain 
\begin{equation*}
(\mathcal{F}_c{W})(\tau,\eta)=C(\mathcal{F}_c\widetilde{a})(\eta)\in \mathcal{S}(\mathbb{R}^2),\qquad \tau\in\mathbb{R},\qquad \eta\in\mathbb{R}^2.
\end{equation*}
Then 
\begin{equation*}
    \|W\|^2_{H^{-1}(\mathbb{R}^3)}=\int_{\mathbb{R}^2}|(\mathcal{F}_c{\widetilde{a}})(\eta)|^2\int_{\mathbb{R}}(1+\tau^2+|\eta|^2)^{-1}d\tau d\eta<\infty.
\end{equation*}
Therefore, $ 0\neq\phi\in\ell^{2,-1}(\mathbb{Z}^3)$ and $(\Delta+4)\phi=0$, as claimed.

Since $\phi\in\ell^2(\mathbb{Z}^3)$ and $H\phi=4\phi$, taking the Fourier transform gives
\begin{equation}\label{m-4 and f}
(\mathcal{M}(\xi)-4)(\mathcal{F}\phi)(\xi)=-\mathcal{F}(V\phi)(\xi).
\end{equation}
Let $f=\mathcal{F}(V\phi)$. Choose $\frac{5}{2}<s\leq\beta$. Then $f\in H^s(\mathbb{T}^3)$, and hence $f\in C^1(\mathbb{T}^3)$ by the Sobolev embedding theorem. We claim that $f|_{\mathcal{M}_4}=0$. Once this holds, then by Lemma \ref{Taira lemma} (2), we have 
\begin{equation*}
    (\mathcal{M}(\xi)-4\mp i0)^{-1}f(\xi)=(\mathcal{M}(\xi)-4)^{-1}f(\xi),
\end{equation*}
which combined with \eqref{m-4 and f} gives $\phi+(-\Delta-4\mp i0)^{-1}V\phi=0.$ 

To prove $f|_{\mathcal{M}_4}=0$, we first consider $\xi_0\in \mathcal{M}_4\setminus\Sigma_4$, where $\Sigma_4$ is defined in \eqref{Sigma4}. Since $(\nabla\mathcal{M})(\xi_0)\neq0$, there exist a neighborhood $U(\xi_0)$ of $\xi_0$ and a constant $c(\xi_0)>0$, such that $|(\nabla\mathcal{M})(\xi)|\geq c(\xi_0)>0$ for all $\xi\in U(\xi_0)$. 

Choose an open neighborhood $U_1$ of $\xi_0$ such that $\overline{U_1}\subset U(\xi_0)$, and take $0\leq \varphi\in C_0^\infty(U(\xi_0))$ satisfying $\varphi\equiv1\  \text{on } U_1.$  Let $0\leq \rho\in C^{\infty}_0((-1,1))$ with $\int_{\mathbb{R}}\rho(s)ds=1$ and 
$\rho_{\varepsilon}(s)=\varepsilon^{-1}\rho(s\varepsilon^{-1})$. By Lemma \ref{coarea formula lemma},
\begin{equation*}
\int_{\mathbb{T}^3}\varphi(\xi)|f(\xi)|^2\rho_{\varepsilon}(\mathcal{M}(\xi)-4)d\xi=\int_{0}^{12}\rho_{\varepsilon}(\lambda-4)\int_{\mathcal{M}_{\lambda}}\frac{\varphi(\xi)|f(\xi)|^2d\sigma_{\lambda}(\xi)}{|(\nabla\mathcal{M})(\xi)|}d\lambda\rightarrow\int_{\mathcal{M}_{4}}\frac{\varphi(\xi)|f(\xi)|^2d\sigma_{4}(\xi)}{|(\nabla\mathcal{M})(\xi)|}
\end{equation*}
as $\varepsilon\rightarrow0$. On the other hand, by \eqref{m-4 and f} and the uniform boundedness of $s^2\rho(s)$, we have
\begin{equation*}
\Big|\int_{\mathbb{T}^3}\varphi(\xi)|f(\xi)|^2\rho_{\varepsilon}(\mathcal{M}(\xi)-4)d\xi\Big|=\Big|\int_{\mathbb{T}^3}\varphi(\xi)(\mathcal{M}(\xi)-4)^2|(\mathcal{F}\phi)(\xi)|^2\rho_{\varepsilon}(\mathcal{M}(\xi)-4)d\xi\Big|\lesssim  \varepsilon\rightarrow0.
\end{equation*}
Consequently, the continuity of $f$ implies that $f(\xi)=0$ on $\mathcal{M}_4\cap \{\varphi(\xi)>0\}$. In particular, since $\varphi(\xi_0)=1>0$, it follows that $f(\xi_0)=0$. It remains to consider $\xi\in\Sigma_4$. By the Morse lemma, there exist neighborhoods $U(\xi)$ of $
\xi$ and $V_0$ of $0$, and a $C^{\infty}$ diffeomorphism $G: U(\xi)\longrightarrow V_0$ such that
\begin{equation*}
    G(\xi)=0\quad {\rm and}\quad \mathcal{M}(G^{-1}(\eta))-4=-|\eta'|^2+|\eta''|^2=:F(\eta), \quad \eta=(\eta',\eta''),\quad \eta'\in \mathbb{R},\quad \eta''\in \mathbb{R}^2.
    \end{equation*}
Choose unit vector $e'\in\mathbb{R}$ and $e''\in\mathbb{R}^2$, and set $\eta_r=(re',re'')$ with $r>0$. Then   
$$F(\eta_r)=0,\quad (\nabla F)(\eta_r)=(-2re',2re'')\neq 0,\quad  \lim\limits_{r\rightarrow0}\eta_r=0.$$
Define $\xi_r:=G^{-1}({\eta_r})$. Then $\xi_r\in \mathcal{M}_4\setminus\Sigma_4$ by  $\mathcal{M}(\xi_r)=4+F(\eta_r)=4$ and $(\nabla\mathcal{M})(\xi_r)\neq0$. Moreover, 
\begin{equation*}
\quad \xi=G^{-1}(0)=\lim\limits_{r\rightarrow0}G^{-1}(\eta_r)=\lim\limits_{r\rightarrow0}\xi_r.
\end{equation*}
By the result above and the continuity of $f$, we have $f(\xi)=\lim\limits_{r\rightarrow0}f(\xi_r)=0$. Therefore, $f|_{\mathcal{M}_4}=0$.

\label{prop of Ak calcul}
The expansion \eqref{expan of R0} holds. Moreover, $(-\Delta)A_0=\delta_0$, and the kernel $A_k(n-m)$ of $A_k$ for odd $k$ is given by
\begin{equation}\label{Ak for odd k}
 A_k(n)=\frac{i(\frac{k-1}{2})!}{4\pi k!}\sum\limits_{\substack{k_1+k_2+k_3=\frac{k-1}{2}\\  k_1,k_2,k_3\in \mathbb{N}}} \prod\limits_{j=1}^{3}\frac{(\frac{1}{2}-n_j)_{k_j}(\frac{1}{2}+n_j)_{k_j}}{k_j!},\quad n=(n_1,n_2,n_3)\in\mathbb{Z}^3
\end{equation}
with $(a)_{\ell}:=a(a+1)\cdots(a+\ell-1)$ for integer $\ell\geq1$ and $ (a)_0=1$. As a consequence, $A_1(n)=\frac{i}{4\pi}$.

Fix $0<\delta<1$ and let $0<|\omega|<\delta/2$ with $0<\arg\omega<2\pi$. We decompose $R_0(\omega,n)$ as 
\begin{equation}\label{decom of R0}
R_0(\omega,n)=\frac{1}{8\pi^3}\Big(\int_{\{\mathcal{M}(\theta)<\delta\}}+\int_{\{\mathcal{M}(\theta)\geq\delta\}}\Big)\frac{e^{-i\theta\cdot n}}{\mathcal{M}(\theta)-\omega}d\theta=:R_{01}(\omega,n)+R_{02}(\omega,n).
\end{equation}
Clearly, $R_{02}(\omega,n)$ is analytic in $0<|\omega|<\delta/2$. Moreover, for every $k\in\mathbb{N}$, the derivative $(\partial^{k}_\omega R_{02})(\omega,n)$ is uniformly bounded in $n$ and $0<|\omega|<\delta/2$. It remains to analyze $R_{01}(\omega,n)$. Making the change of variables 
\begin{equation*}
s_j=2\sin\frac{\theta_j}{2}, \qquad g(s_j)=2\arcsin{\frac{s_j}{2}},\qquad s=(s_1,s_2,s_3),
\end{equation*}
and using the polar coordinates $s=rs'$, $s'\in\mathbb{S}^2$, we have 
\begin{equation}\label{expre of R01}
    R_{01}(\omega,n)=\frac{1}{8\pi^3}\int_{0}^{\sqrt{\delta}}\frac{r^2}{r^2-\omega}F(r,n)dr,\qquad F(r,n)=\int_{\mathbb{S}^2}\prod\limits_{j=1}^{3}e^{-ig(rs'_j)n_j}g'(rs'_j)d\sigma(s'),
\end{equation}
where $d\sigma(s')$ denotes the surface measure on the unit sphere $\mathbb{S}^2$.
By symmetry, we note that
\begin{equation*}
F(r,n)=\int_{\mathbb{S}^2}G(r,s,n)d\sigma(s),\quad G(r,s,n)=\prod\limits_{j=1}^{3}g_{n_j}(rs_j),\quad g_{m}(x)={\rm cos}(mg(x))g'(x).
\end{equation*}
For any integer $M$, applying Taylor expansion to $G(r,s,n)$ near $r=0$, we obtain
\begin{equation*}
G(r,s,n)=\sum\limits_{k=0}^{M}\frac{1}{k!}(\partial^k_rG)(0,s,n)r^k+G_{M}(r,s,n).
\end{equation*}
Since $G$ is an even function about $r$, it follows that $(\partial^k_rG)(0,s,n)=0$ if $k$ is odd. Moreover, 
\begin{equation*}
G_{M}(r,s,n)=\begin{cases}
    \frac{r^{M+1}}{M!}\int_{0}^{1}(1-t)^{M}(\partial^{M+1}_rG)(tr,s,n)dt,&M\ is\ odd,\\
    \frac{r^{M+2}}{(M+1)!}\int_{0}^{1}(1-t)^{M+1}(\partial^{M+2}_rG)(tr,s,n)dt,&M\ is\ even.
\end{cases} 
\end{equation*}
Consequently, 
\begin{equation}\label{expan of Frn}
F(r,n)=\sum\limits_{k=0}^{M}f_{k}(n)r^k+E_{M}(r,n), \quad 0<r<\sqrt{\delta}
\end{equation}
with 
\begin{equation*}
f_k(n)=\frac{1}{k!}\int_{\mathbb{S}^2}(\partial^k_rG)(0,s,n)d\sigma(s),\qquad  E_{M}(r,n)=\int_{\mathbb{S}^2}G_M(r,s,n)d\sigma(s).
\end{equation*}
It is clear that $f_k(n)=0$ if $k$ is odd. Next we claim that
\begin{equation}\label{fk for even k}
f_k(n)=\frac{4\pi(\frac{k}{2})!}{(k+1)!}\sum\limits_{\substack{k_1+k_2+k_3=\frac{k}{2}\\  k_1,k_2,k_3\in \mathbb{N}}} \prod\limits_{j=1}^{3}\frac{(\frac{1}{2}-n_j)_{k_j}(\frac{1}{2}+n_j)_{k_j}}{k_j!},\qquad \text{if $k$ is even}, 
\end{equation}
and $E_{M}(r,n)$ satisfies the following estimate
\begin{equation}\label{estimate of fN21}
    |E_{M}(r,n)|\lesssim \begin{cases}
r^{M+1}\left<n\right>^{M+1}, &M\ is\ odd,\\
r^{M+2}\left<n\right>^{M+2}, &M\ is\ even,
    \end{cases}\qquad 0<r<\sqrt{\delta}.
\end{equation}
Indeed, first, by Leibniz's rule, 
\begin{equation}\label{leibniz of G}
(\partial^k_rG)(r,s,n)=\sum\limits_{\substack{k_1+k_2+k_3=k\\  k_1,k_2,k_3\in \mathbb{N}}} \frac{k!}{k_1!k_2!k_3!}\prod\limits_{j=1}^{3}s_j^{k_j}g^{(k_j)}_{n_j}(rs_j).
\end{equation}
We note that $
(4-x^2)g''_m(x)-3xg'_m(x)+(4m^2-1)g_m(x)=0$ for $ |x|<2.
$
This together with 
\begin{equation*}
g_m(x)=\sum\limits_{j=0}^{+\infty}b_j(m)x^{2j},\quad b_j(m)=\frac{g^{(2j)}_m(0)}{(2j)!},
\end{equation*}
yields $
    4(2j+2)(2j+1)b_{j+1}(m)+(4m^2-(2j+1)^2)b_j(m)=0$ and thus 
    $$g^{(2(j+1))}_{m}(0)=((j+\frac{1}{2})^2-m^2)g^{(2j)}_{m}(0)\Longrightarrow g^{(2j)}_{m}(0)=(\frac{1}{2}-m)_{j}(\frac{1}{2}+m)_{j}.$$
Hence, if $k$ is even, using \eqref{leibniz of G} and $$\int_{\mathbb{S}^2}s^{2k_1}_1s^{2k_2}_2s^{2k_3}_3d\sigma(s)=\frac{4\pi}{(k+1)!!}\prod\limits_{j=1}^{3}(2k_j-1)!!,$$ where $k_1+k_2+k_3=\frac{k}{2}$, we derive \eqref{fk for even k}.
To estimate the remainder term, since
$$g_m(x)=\frac{1}{2}(e^{img(x)}+e^{-img(x)})g'(x),\qquad(e^{\pm img(x)})^{(k)}(x)=e^{\pm img(x)} P_{k,m}(x),$$
where $P_{k,m}(x)$ is a polynomial in $m$ of degree at most $k$, and each of its coefficients is a finite product and linear combination of $\{g^{(j)}(x)\}^k_{j=0}$. This together with \eqref{leibniz of G} implies \eqref{estimate of fN21}. Taking \eqref{expan of Frn} into \eqref{expre of R01} yields
\begin{equation}\label{expre2 of R01}
R_{01}(\omega,n)=\frac{1}{8\pi^3}\sum\limits_{k=0}^{M}f_k(n)\int_{0}^{\sqrt{\delta}}\frac{r^{k+2}}{r^2-\omega}dr+\frac{1}{8\pi^3}\int_{0}^{\sqrt{\delta}}\frac{r^{2}E_{M}(r,n)}{r^2-\omega}dr.
\end{equation}
If $k$ is even, using 
$r^{k+2}=r^{2(\frac{k}{2}+1)}-\omega^{\frac{k}{2}+1}+\omega^{\frac{k}{2}+1}$, we derive 
\begin{equation}\label{fk rk integral}
f_k(n)\int_{0}^{\sqrt{\delta}}\frac{r^{k+2}}{r^2-\omega}dr=\frac{\pi i}{2}\omega^{\frac{k+1}{2}}f_k(n)+\Big(\underbrace{\sum\limits_{j=0}^{\frac{k}{2}}a_j(k)\omega^j+\frac{1}{2}\omega^{\frac{k+1}{2}}\ln\frac{1-\sqrt{\frac{\omega}{\delta}}}{1+\sqrt{\frac{\omega}{\delta}}}}_{=:P_k(\omega)\ \text{is analytic in}\ \omega }\Big)f_k(n).
\end{equation}
Since $f_k(n)=0$ when $k$ is odd. Thus, this formula is valid for any $k\in\mathbb{N}$.
\vskip0.1cm
We now analyze the remainder integral in \eqref{expre2 of R01}. Fix a sufficiently small $0<\varepsilon\ll1$. We further restrict $\omega$ to $\varepsilon\leq \arg\omega\leq 2\pi-\varepsilon$. Let $q=[\frac{M+1}{2}]$. Using 
\begin{equation*}
    \frac{r^2}{r^2-\omega}=\sum\limits_{j=0}^{q}\omega^j r^{-2j}+\omega^{q+1}\frac{r^{-2q}}{r^2-\omega},
\end{equation*}
and the estimate \eqref{estimate of fN21}, we write
\begin{equation}\label{expre of remainder}
\int_{0}^{\sqrt{\delta}}\frac{r^{2}E_{M}(r,n)}{r^2-\omega}dr=Q_M(\omega,n)+\omega^{q+1}\int_{0}^{\sqrt{\delta}}\frac{r^{-2q}}{r^2-\omega}E_M(r,n)dr,
\end{equation}
where $Q_M(\omega,n)$ is a polynomial in $\omega$. For the second term, we claim that 
\begin{equation}\label{estimate for w qplus1}
\Big|\omega^{q+1}\int_{0}^{\sqrt{\delta}}\frac{r^{-2q}}{r^2-\omega}E_M(r,n)dr\Big|=O(|\omega|^{\frac{M+2}{2}}\left<n\right>^{M+1}). 
\end{equation}
Indeed, if $M$ is odd, then $q=\frac{M+1}{2}$. Since $\varepsilon\leq \arg\omega\leq 2\pi-\varepsilon$, we have the following estimate 
\begin{equation*}
    |r^2-\omega|\gtrsim r^2+|\omega|.
\end{equation*}
Combining this with \eqref{estimate of fN21}, we obtain 
\begin{equation*}
\Big|\omega^{q+1}\int_{0}^{\sqrt{\delta}}\frac{r^{-2q}}{r^2-\omega}E_M(r,n)dr\Big|\lesssim |\omega|^{q+1}\int_{0}^{\sqrt{\delta}}\frac{dr}{r^2+|\omega|}\left<n\right>^{M+1}\lesssim |\omega|^{\frac{M+2}{2}}\left<n\right>^{M+1}.
\end{equation*}
If $M$ is even, then $q=\frac{M}{2}$. Let $C_{n,\delta}=\min\{\left<n\right>^{-1},\sqrt{\delta}\}$. 
We divide the integral into two parts
\begin{equation*}
\int_{0}^{\sqrt{\delta}}\frac{r^{-2q}}{r^2-\omega}E_M(r,n)dr=\Big(\int_{0}^{C_{n,\delta}}+\int_{C_{n,\delta}}^{\sqrt{\delta}}\Big)\frac{r^{-M}}{r^2-\omega}E_M(r,n)dr=:(I_1+I_2)(M,\omega,n).
\end{equation*}
It is clear that 
\begin{equation*}
    |I_1(M,\omega,n)|\lesssim \left<n\right>^{M+2}\int_{0}^{C_{n,\delta}}\frac{r^2}{r^2+|\omega|}dr\lesssim \left<n\right>^{M+1}.
\end{equation*}
Since $F(r,n)$ is uniformly bounded in $r\in [0,\sqrt{\delta}]$ and $n\in\mathbb{Z}^3$, and $|f_{2j}(n)|\lesssim \left<n\right>^{2j}$,  when $r\left<n\right>\geq1$, we have
\begin{equation*}
    |E_{M}(r,n)|=\Big|F(r,n)-\sum\limits_{j=0}^{q}f_{2j}(n)r^{2j}\Big|\lesssim r^{M}\left<n\right>^{M}.
\end{equation*}
Then 
\begin{equation*}
|I_2(M,\omega,n)|\lesssim \left<n\right>^{M}\int_{C_{n,\delta}}^{\sqrt{\delta}}\frac{dr}{r^2}\leq \left<n\right>^{M}\int_{\left<n\right>^{-1}}^{+\infty}\frac{dr}{r^2}\leq \left<n\right>^{M+1}.
\end{equation*}
Therefore, we obtain \eqref{estimate for w qplus1}. Combining \eqref{fk rk integral}, \eqref{expre of remainder}, \eqref{estimate for w qplus1}, \eqref{expre2 of R01} and \eqref{decom of R0}, we obtain 
\begin{align*}
    R_{0}(\omega,n)=\sum\limits_{k=1}^{M+1}\frac{if_{k-1}(n)}{16\pi^2}\omega^{\frac{k}{2}}+\frac{1}{8\pi^3}\Big(\sum\limits_{k=0}^{M}P_k(\omega)f_k(n)+Q_M(\omega,n)\Big)+R_{02}(\omega,n)+O(|\omega|^{\frac{M+2}{2}}\left<n\right>^{M+1}),
\end{align*}
which gives \eqref{expan of R0} by letting $N=M+1$. Moreover, if $k$ is odd,  $A_k(n)=\frac{if_{k-1}(n)}{16\pi^2}$. This combined with \eqref{fk for even k} yields \eqref{Ak for odd k}. 
As a consequence,  $R_0(\omega,n)=A_0(n)+\widetilde{A}(\omega,n)$ with $|\widetilde{A}(\omega,n)|=O(|\omega|^{1/2})$. We first fix $\omega=a+ib~(b\neq0)$ and $|\omega|<\delta/2$. Since for any $n\in\mathbb{Z}^3$, $\big((-\Delta-\omega)R_0(\omega,\cdot)\big)(n)=\delta_0(n)$. Hence, 
\begin{equation*}
\delta_0(n)+\omega R_0(\omega,n)=\big((-\Delta)R_0(\omega,\cdot)\big)(n)=\big((-\Delta)A_0(\cdot)\big)(n)+\big((-\Delta)\widetilde{A}(\omega,\cdot))(n).  
\end{equation*}
Letting $\omega\rightarrow0$, we then derive $\big((-\Delta)A_0(\cdot)\big)(n)=\delta_0(n)$ and prove that $(-\Delta)A_0=\delta_0$.

\label{prop of B0 calcu}
Let $B^\pm_0$ and $E^\pm_0$ be defined in \eqref{expan at 4}. Then we have
\begin{equation*}
B^\pm_0(n)=\frac{\mp}{4\pi}\big((-1)^{n_1}+(-1)^{n_2}+(-1)^{n_3}\big),\quad (-\Delta-4)E^\pm_0=\delta_0.
\end{equation*}

Fix $0<\delta<1$, and let $0<|\omega|<\min\{\frac{\delta}{2},\mu\}$, where $\mu$ will be specified later. By the conjugation symmetry, it suffices to consider the case $\operatorname{Im}\omega>0.$  Choose a partition of unity $$\sum\limits_{j=1}^{3}\xi_j(\theta)+\chi(\theta)+\eta(\theta)=1,$$
where the functions  $\xi_j(\theta)$ are later determined so that $\xi_j(\theta)=1$ in a neighborhood of $\pi e_j$ and
$$\operatorname{supp}\chi \subseteq \{|\mathcal{M}(\theta)-4|<\delta\} \setminus \bigcup_{j=1}^{3}\operatorname{supp}\xi_j, \qquad \operatorname{supp}\eta \subseteq \{|\mathcal{M}(\theta)-4|\geq\delta\}.$$
Accordingly, we decompose
\begin{equation*}
R_0(4+\omega,n)=\sum\limits_{j=1}^{3}\underbrace{\int_{\mathbb{T}^3}\frac{e^{-i\theta\cdot n}\xi_j(\theta)}{8\pi^3(\mathcal{M}(\theta)-4-\omega)}d\theta}_{:=K_j(\omega,n)}+\underbrace{\int_{\mathbb{T}^3}\frac{e^{-i\theta\cdot n}\chi(\theta)}{8\pi^3(\mathcal{M}(\theta)-4-\omega)}d\theta}_{:=K_r(\omega,n)}+\underbrace{\int_{\mathbb{T}^3}\frac{e^{-i\theta\cdot n}\eta(\theta)}{8\pi^3(\mathcal{M}(\theta)-4-\omega)}d\theta}_{:=K_a(\omega,n)}.
\end{equation*}

Clearly, $K_a(\omega,n)$ is analytic in $\omega$ and hence contributes only integer powers of $\omega$. We next show that the same holds for $K_r(\omega,n)$. Consequently, all half-integer contributions arise from the terms $K_j(\omega,n)$. Following the argument in the proof of \cite[Proposition 2.6]{Kop09}, we then compute the leading half-integer coefficient $B_0^+(n)$.
\vskip0.2cm
\underline{ \bf (1) The analyis of $K_r$.} Choose a finite partition of unity 
$$\chi(\theta)=\sum_{j=1}^{N_0}\chi_j(\theta), \qquad \chi_j\in C^\infty_0(\mathbb{T}^3),$$
with each $\operatorname{supp}\chi_j$ sufficiently small and contained in $\operatorname{supp}\chi$. Then
\begin{equation*}
    K_r(\omega,n)=\frac{1}{8\pi^3}\sum\limits_{j=1}^{N_0}\int_{\mathbb{T}^3}\frac{e^{-i\theta\cdot n}\chi_j(\theta)}{\mathcal{M}(\theta)-4-\omega}d\theta=:\frac{1}{8\pi^3}\sum\limits_{j=1}^{N_0}K_{rj}(\omega,n),\quad \chi_j\in C^{\infty}_0({\rm supp}\chi).
\end{equation*}
Let $S_j=\operatorname{supp}\chi_j\cap\mathcal{M}_4$. If $S_j=\varnothing$, then $K_{rj}(\omega,n)$ is clearly analytic in $\omega$. Suppose therefore that $S_j\neq\varnothing$. Then any $\theta\in\operatorname{supp}\chi_j$ can be represented uniquely as $$\theta=s+t\mathbf{n}(s),\qquad  s\in S_j,$$
where $\mathbf{n}(s):=(\nabla\mathcal{M})(s)/|(\nabla\mathcal{M})(s)|$ is the outward unit normal vector at $s$. By the mean value theorem, 
\begin{equation*}
\mathcal{M}(\theta)-4=\mathcal{M}(s+t\mathbf{n}(s))-\mathcal{M}(s)=t\int_{0}^{1}\mathbf{n}(s)\cdot(\nabla\mathcal{M})(s+t\rho\mathbf{n}(s)) d\rho=:u(s,t).
\end{equation*}
Denote by $d\sigma(s)$ the surface measure on $S_j$. Then 
\begin{equation*}
    K_{rj}(\omega,n)=\int_{S_j}d\sigma(s)\int_{-a(s)}^{b(s)}\frac{e^{-i(s+t\mathbf{n}(s))\cdot n}\chi_j(s+t\mathbf{n}(s))J(s,t)}{u(s,t)-\omega}dt,
\end{equation*}
where $J(s,t)$ is the Jacobian and $a(s),b(s)>0$. Since $(\partial_tu)(s,0)=|(\nabla\mathcal{M})(s)|>0$ for any $s\in S_j$. Define 
$$\gamma_j:=\frac{1}{2}\min\limits_{s\in S_j}|(\nabla\mathcal{M})(s)|.$$
By the compactness of $S_j$, there exists $\tau_j>0$, independent of $s$, such that $[-\tau_j,\tau_j]\subseteq(-a(s),b(s))$ and 
$$(\partial_tu)(s,t)\geq \gamma_j>0,\qquad s\in S_j,\quad |t|\le\tau_j.$$
Denote 
$$\widetilde{\chi}_j(s,t,n)=e^{-i(s+t\mathbf{n}(s))\cdot n}\chi_j(s+t\mathbf{n}(s))J(s,t).$$
Let
$$\mathcal I_j := \bigl\{(s,t):s\in S_j,\, t\in(-a(s),b(s))\setminus[-\tau_j,\tau_j]\bigr\} \cap\operatorname{supp}\widetilde\chi_j.$$
Since $u(s,t)\neq0$ on $\mathcal I_j$, compactness yields
$$m_j:=\min\limits_{(s,t)\in\mathcal{I}_j}|u(s,t)|>0.$$ Choose 
$$0<a_j<\frac12\min\{m_j,\gamma_j\tau_j\},$$
and $\zeta\in C^{\infty}_0((-a_j,a_j))$, $0\leq \zeta\leq1$ and $\zeta(x)=1$ for $|x|\leq \frac{a_j}{2}$. Let $0<|\omega|<\min\limits_{1\leq j\leq N_0}\{\frac{a_j}{4}\}=:\mu$. We decompose 
\begin{align*}
    K_{rj}(\omega,n)&=\int_{S_j}d\sigma(s)\int_{-a(s)}^{b(s)}\frac{\zeta(u(s,t))\widetilde{\chi}_j(s,t,n)}{u(s,t)-\omega}dt+\int_{S_j}d\sigma(s)\int_{-a(s)}^{b(s)}\frac{(1-\zeta(u(s,t)))\widetilde{\chi}_j(s,t,n)}{u(s,t)-\omega}dt.
\end{align*}
Since supp $(1-\zeta(x))\subseteq\{|x|\geq \frac{a_j}{2}\}$, and therefore the second term is analytic in $\omega$. It remains to consider
\begin{equation*}
    \widetilde{K}_{rj}(\omega,n):=\int_{S_j}d\sigma(s)\int_{-a(s)}^{b(s)}\frac{\zeta(u(s,t))\widetilde{\chi}_j(s,t,n)}{u(s,t)-\omega}dt
\end{equation*}
By the choice $a_j<m_j/2$, the condition
$\zeta(u(s,t))\neq0$ implies $|t|<\tau_j$. Moreover, our choice $a_j<\gamma_j\tau_j/2$ guarantees that the inverse
$t=t(s,u)$ is well-defined for every $s\in S_j$ and $|u|<a_j.$ Therefore, by the change of variables $u=u(s,t)$, we obtain
\begin{equation*}
    \widetilde{K}_{rj}(\omega,n)=\int_{-a_j}^{a_j}\frac{1}{u-\omega}\int_{S_j}\zeta(u)\widetilde{\chi}_j(s,t(s,u),n)(\partial_ut)(s,u)d\sigma(s)du=:\int_{-a_j}^{a_j}\frac{A_j(u,n)}{u-\omega}du.
\end{equation*}
By definition, for each $n$, 
 $A_j(\cdot,n)\in C^{\infty}_0((-a_j,a_j))$, and for every $k\in\mathbb{N}$, 
 \begin{equation}\label{estima of parkuA_j}
  \sup\limits_{|u|\leq  a_j}|(\partial^k_uA_j)(u,n)|\lesssim\left<n\right>^{k}.   
 \end{equation}
 Since Im$\omega>0$, 
 $$\partial_\omega^k\frac1{u-\omega} = \frac{k!}{(u-\omega)^{k+1}}, \qquad \partial_u^k\frac1{u-\omega} = (-1)^k\frac{k!}{(u-\omega)^{k+1}}.$$
 Hence, integrating by parts $k$ times and using
$A_j(\cdot,n)\in C^\infty_0((-a_j,a_j))$, we obtain
\begin{equation*}
(\partial^k_{\omega}\widetilde{K}_{rj})(\omega,n)=k!\int_{-a_j}^{a_j}\frac{A_j(u,n)}{(u-\omega)^{k+1}}du=(-1)^k\int_{-a_j}^{a_j}A_j(u,n)\partial^k_u(\frac{1}{u-\omega})du=\int_{-a_j}^{a_j}\frac{(\partial^k_uA_j)(u,n)}{u-\omega}du.
\end{equation*}
For $0<\varepsilon\leq1$, let
$K(\varepsilon):=\widetilde{K}_{rj}(\varepsilon\omega,n)$. Applying Taylor's expansion to $K$ at $\varepsilon$, evaluated at 1, gives
\begin{align*}
  \widetilde{K}_{rj}(\omega,n)= \sum\limits_{k=0}^{N}\frac{\omega^k}{k!}(\partial^k_{\omega}\widetilde{K}_{rj})(\varepsilon\omega,n)(1-\varepsilon)^k+\frac{(\omega(1-\varepsilon))^{N+1}}{N!}\int_{0}^{1}(1-t)^{N}(\partial^{N+1}_{\omega}\widetilde{K}_{rj})((\varepsilon+t(1-\varepsilon))\omega,n)dt.
\end{align*}
Applying \eqref{estima of parkuA_j} and Lemma \ref{cauthy integral lemma} with $h=\min\{\frac{a_j}{4},\left<n\right>^{-1}\}$,we obtain
\begin{equation*}
    \sup\limits_{0<|\omega|<\mu,\ \operatorname{Im}\omega>0}|(\partial^k_{\omega}\widetilde{K}_{rj})(\omega,n)|\lesssim\left<n\right>^{k}(1+\ln(1+\left<n\right>)).
\end{equation*}
Applying this estimate to the remainder and letting $\varepsilon\rightarrow0$, we derive
\begin{align*}
    \widetilde{K}_{rj}(\omega,n)&=\sum\limits_{k=0}^{N}\frac{\omega^k}{k!}\Big((\partial^{k}_uA_j)(0,n)\pi i+\int_{-a_j}^{a_j}\frac{(\partial^{k}_uA_j)(u,n)-(\partial^{k}_uA_j)(0,n)}{u}du\Big)\\
&\quad+O\Big(|\omega|^{N+1}\left<n\right>^{N+1}(1+\ln(1+\left<n\right>))\Big).
\end{align*}
Therefore, we prove that $K_r(\omega,n)$ contributes only integer powers of $\omega$. We now turn to the contributions of $K_j$ and compute $B^+_0(n)$.
\vskip0.2cm
\underline{\bf(2) Calculation of $\bm {B^+_0(n)}$.} To this end, we briefly review and reorganize Kopylova's argument.
Let $$\theta'=\theta-\pi e_j,\qquad\eta_j(\theta')=\xi_j(\theta'+\pi e_j)$$ and choose $\eta_j$ to be even in each variable. Then
\begin{equation*}
K_j(\omega,n)=\frac{(-1)^{n_j}}{8\pi^3}\int_{\mathbb{T}^3}\frac{e^{-i\theta'\cdot n}\eta_j(\theta')d\theta'}{\mathcal{M}(\theta'+\pi e_j)-4-\omega}=\frac{(-1)^{n_j}}{\pi^3}\int_{(0,+\infty)^3}\frac{\prod\limits_{k=1}^{3}{\rm cos}(n_k\theta'_k)\eta_j(\theta')}{\sum\limits_{k=1}^{3}4{\rm sin}^2\frac{\theta'_k}{2}-8{\rm sin}^2\frac{\theta'_j}{2}-\omega}d\theta'.
\end{equation*}
Since the three cases are analogous, it suffices to consider $K_1(\omega,n)$. 
\vskip0.1cm
{\bf Step 1}: We apply the following three changes of variables successively:
\begin{align*}
  &(1)~\theta'=(\theta'_1,\theta'_2,\theta'_3)\rightarrow s=(s_1,s_2,s_3): s_1=2{\rm sin}\frac{\theta'_2}{2},\quad s_2=2{\rm sin}\frac{\theta'_3}{2},\quad s_3=2{\rm sin}\frac{\theta'_1}{2},\\
  &(2)~~s=(s_1,s_2,s_3)\rightarrow (\tau,s_3):~~~~~~~~ s_1=\tau\cos\varphi,\quad s_2=\tau\sin\varphi,\quad s_3=s_3,\\
  &(3)~(\tau,s_3)\rightarrow \rho=(\rho_1,\rho_2):
  \rho_1=\tau^2-s^2_3,\quad \rho_2=2\tau s_3.
\end{align*}
We now specify the cutoff $\eta_1$ so that, under the first change of
variables, 
$$\eta_1(\theta')=\widetilde\eta_1(|s|^2), \qquad |s|^2=s_1^2+s_2^2+s_3^2,$$
where $\widetilde\eta_1\in C^\infty_0([0,\infty))$ is chosen with
sufficiently small support such that
$$\operatorname{supp}\bigl(\widetilde\eta_1(|\rho|)\bigr) \cap\{\rho_2\ge0\} \subset D_\delta := \{(\rho_1,\rho_2):|\rho_1|\le\delta,\ 0\le\rho_2\le\delta\},\qquad |\rho|=\sqrt{\rho^2_1+\rho^2_2}.$$
Then
\begin{align}
K_1(\omega,n)&=\int_{(0,+\infty)^3}\frac{\frac{(-1)^{n_1}}{\pi^3}\prod\limits_{k=1}^{3}{\rm cos}(n_k\theta'_k)\eta_1(\theta')d\theta'}{4\big({\rm sin}^2\frac{\theta'_2}{2}+{\rm sin}^2\frac{\theta'_3}{2}-{\rm sin}^2\frac{\theta'_1}{2}\big)-\omega}\xlongequal[]{(1)}\frac{(-1)^{n_1}}{\pi^3}\int_{(0,+\infty)^3}\frac{F_1(n,s^2_1,s^2_2,s^2_3)\widetilde{\eta}_1(|s|^2)}{s^2_1+s^2_2-s^2_3-\omega}ds\notag\\
&\xlongequal[]{(2)}\frac{(-1)^{n_1}}{\pi^3}\int_{(0,+\infty)^2}\frac{\tau\widetilde{\eta}_1(\tau^2+s^2_3)}{\tau^2-s^2_3-\omega}\mathbb{F}_1(n,\tau^2,s^2_3)d\tau ds_3,\notag\\
&\xlongequal[]{(3)}\frac{(-1)^{n_1}}{\pi^3}\int_{0}^{\delta}\int_{-\delta}^{\delta}\frac{\sqrt{r+\rho_1}}{(\rho_1-\omega)r}H_1(r,\rho_1,n)d\rho_1 d\rho_2,\quad r=|\rho|,\label{expre of K1 after transform}
\end{align}
where $g(x)=2{\arcsin}\frac{x}{2}$, $G(s)=\Big((1-\frac{s^2_1}{4})(1-\frac{s^2_2}{4})(1-\frac{s^2_3}{4})\Big)^{-1/2}$ and 
\begin{align*}
&F_1(n,s^2_1,s^2_2,s^2_3)={\rm cos}(n_1g(s_3)){\rm cos}(n_2g(s_1)){\rm cos}(n_3g(s_2))G(s),\\
&\mathbb{F}_1(n,\tau^2,s^2_3)=\int_{0}^{\frac{\pi}{2}}F_1(n,\tau^2\cos^2\varphi,\tau^2\sin^2\varphi,s^2_3)d\varphi,\quad
H_1(r,\rho_1,n)=\frac{\widetilde{\eta}_1(r)}{4\sqrt{2}}\mathbb{F}_1(n,\frac{r+\rho_1}{2},\frac{r-\rho_1}{2}).
\end{align*}
\vskip0.1cm
{\bf Step 2}: Let $N$ be an integer. Applying Taylor expansion to $H_1(r,\rho_1,n)$ near $\rho_1=0$, we derive
\begin{equation*}
H_1(r,\rho_1,n)=\sum\limits_{k=0}^{N}\frac{(\partial^{k}_{\rho_1}H_1)(r,0,n)}{k!}\rho^k_1+h_N(r,\rho_1,n)\rho^N_1,\quad |\rho_1|\leq \delta,
\end{equation*}
where $(\partial^{k}_{\rho_1}H_1)(r,0,n)$ is a polynomial in $n$ of order $2k$ and $$|(\partial^j_{\rho_1}h_N)(r,\rho_1,n)| \lesssim  \left<n\right>^{2N+2j}\ {\rm for\ } j=0,1.$$ 
Substituting this expansion into \eqref{expre of K1 after transform} and using \cite[(2.19)--(2.21), (2.29) and Lemma 2.8]{Kop09}, we obtain

\begin{align*}
K_1(\omega,n)&=\frac{(-1)^{n_1}}{\pi^3}\sum\limits_{k=0}^{N}\Big(\sum\limits_{j=0}^{k-1}a_{k,j}(n)\omega^j+\omega^k\int_{0}^{\delta}\Big(\pi i-\ln\frac{1-\sqrt{\frac{r-\omega}{2r}}}{1+\sqrt{\frac{r-\omega}{2r}}} \Big)\frac{(\partial^{k}_{\rho_1}H_1)(r,0,n)}{k!\sqrt{r-\omega}}dr\Big)\\
&\quad+\sum\limits_{j=0}^{N-1}b_j(N,n)\omega^j+O(\left<n\right>^{2N}(1+\ln\left<n\right> )^2|\omega|^N).
\end{align*}
Applying Taylor's expansion once more to each $(\partial_{\rho_1}^k H_1)(r,0,n)$ near $r=0$, up to order $N-k$, and using \cite[Lemma 2.7 and (2.24)--(2.28)]{Kop09}, we further obtain
\begin{align*}
K_1(\omega,n)&=\frac{(-1)^{n_1}}{\pi^3}\sum\limits_{\ell=0}^{N}\Big(\sum\limits_{k=0}^{\ell}\frac{(\partial^{\ell-k}_{r}\partial^{k}_{\rho_1}H_1)(0,0,n)}{k!(\ell-k)!}c_{\ell-k}\Big)\omega^{\ell+\frac{1}{2}}+\sum\limits_{k=0}^{N}\sum\limits_{j=0}^{N}d(k,j,N,n)\omega^j\\
&\quad +O(\left<n\right>^{2N}(1+\ln\left<n\right> )^2|\omega|^N),
\end{align*}
where $(\partial^{\ell}_{r}\partial^{k}_{\rho_1}H_1)(0,0,n)$ is a polynomial in $n$ of order $2(k+\ell)$ and $c_{\ell}$ denotes the coefficient of $\omega^{\ell+\frac{1}{2}}$ in the expansion of the integral below (see also \cite[Lemma 2.7]{Kop09})
\begin{equation*}
    \int_{0}^{\delta}\Big(\pi i-\ln \frac{1-\sqrt{\frac{r-\omega}{2r}}}{1+\sqrt{\frac{r-\omega}{2r}}}\Big)\frac{r^{\ell}dr}{\sqrt{r-\omega}},\qquad 0<|\omega|<\frac{\delta}{2},\qquad \operatorname{Im}\omega>0.
\end{equation*}
In particular, $c_0=-2\sqrt{2}\pi$ (this value corrects the miscalculation in the original \cite[Appendix A]{Kop09}). Applying this method to $j=2,3$, a similar expansion of $K_j(\omega,n)$ is obtained by replacing $H_1$ with $H_j$, where 
 \begin{equation*}
H_j(r,\rho_1,n)=\frac{\widetilde{\eta}_j(r)}{4\sqrt{2}}\mathbb{F}_j(n,\frac{r+\rho_1}{2},\frac{r-\rho_1}{2}),\quad \mathbb{F}_j(n,\tau^2,s^2_3)=\int_{0}^{\frac{\pi}{2}}F_j(n,\tau^2\cos^2\varphi,\tau^2\sin^2\varphi,s^2_3)d\varphi
 \end{equation*}
with $\widetilde{\eta}_j(r)$ satisfying the same property as $\widetilde{\eta}_1(r)$ and
\begin{equation*}
F_j(n,s^2_1,s^2_2,s^2_3)=G(s)
\begin{cases}
        {\rm cos}(n_1g(s_1)){\rm cos}(n_2g(s_3)){\rm cos}(n_3g(s_2)),&j=2\\
        {\rm cos}(n_1g(s_1)){\rm cos}(n_2g(s_2)){\rm cos}(n_3g(s_3)),&j=3
 \end{cases}\ .
\end{equation*}
Hence, we obtain 
\begin{equation*}
B^+_{\ell}(n)=\sum\limits_{j=1}^{3}\frac{(-1)^{n_j}}{\pi^3}\Big(\sum\limits_{k=0}^{\ell}\frac{(\partial^{\ell-k}_{r}\partial^{k}_{\rho_1}H_j)(0,0,n)}{k!(\ell-k)!}c_{\ell-k}\Big)
\end{equation*}
In particular, if $\ell=0$, we can compute all $H_j(0,0,n)=\frac{\pi}{8\sqrt{2}}$ and this together with $c_0=-2\sqrt{2}\pi$ gives 
 \begin{equation*}
B^+_0(n)=c_0\sum\limits_{j=1}^{3}\frac{(-1)^{n_j}}{\pi^3}H_j(0,0,n)=-\frac{1}{4\pi}\big((-1)^{n_1}+(-1)^{n_2}+(-1)^{n_3}\big).
\end{equation*}
Moreover, by the method used for $A_0$ in Proposition \ref{prop of Ak calcul}, we can also verify $(-\Delta-4)E^+_0=\delta_0.$

\label{cauthy integral lemma}
Given $a>0$ and $B\in C^{\infty}_0((-a,a))$. Define 
\begin{equation*}
    F(\omega)=\int_{-a}^{a}\frac{B(u)}{u-\omega}du,\quad \omega =x+iy,\quad x\in \mathbb{R},\quad y>0.
\end{equation*}
Assume that $|\omega|<\frac{a}{2}$. Then for any $0<h\leq \frac{a}{4}$, we have
\begin{equation}\label{esti of Fw}
\sup\limits_{0<|\omega|<\frac{a}{2},\ \operatorname{Im}\omega>0}|F(\omega)|\leq C_a\|B\|_{L^{\infty}}+2h\|B'\|_{L^{\infty}}+4\|B\|_{L^{\infty}}\ln\frac{3a}{2h}.
\end{equation}
Moreover, $$\lim\limits_{\omega\rightarrow0,\ \operatorname{Im}\omega>0}F(\omega)=\int_{-a}^{a}\frac{B(u)-B(0)}{u}du+B(0)i\pi.$$

Let $\omega=x+iy$ with $y>0$ and $|\omega|<\frac{a}{2}$. We write
    \begin{equation}\label{decom of Fw}
    F(\omega)=B(x)\int_{-a}^{a}\frac{du}{u-\omega}+\int_{-a}^{a}\frac{B(u)-B(x)}{u-\omega}du=:F_1(\omega)+F_2(\omega).
    \end{equation}
 Since $|\omega|\leq a/2$, then by triangle inequality, $a/2\leq |a\pm \omega|\leq 3a/2$. We can compute 
\begin{equation*}
|F_1(\omega)|=\Big|B(x)\Big(\pi i+\ln \frac{a-\omega}{a+\omega}\Big)\Big|\leq C_a\|B\|_{L^{\infty}}.
\end{equation*}
For $F_2(\omega)$, we decompose
\begin{equation*}
    F_2(\omega)=\int_{-a}^{a}\frac{B(u)-B(x)}{u-\omega}du=\Big(\int\limits_{\substack{|u-x|<h\\ |u|<a}}+\int\limits_{\substack{|u-x|\geq h\\ |u|<a}}\Big)\frac{B(u)-B(x)}{u-\omega}du=:F_{21}(\omega)+F_{22}(\omega).
\end{equation*}
By the fundamental theorem of calculus, 
\begin{equation*}
    |F_{21}(\omega)|\leq \|B'\|_{L^{\infty}}\int\limits_{\substack{|u-x|<h\\ |u|<a}}\frac{|u-x|}{|u-x-iy|}du\leq 2h\|B'\|_{L^{\infty}}.
\end{equation*}
On the other hand, 
\begin{equation*}
    |F_{22}(\omega)|\leq 2\|B\|_{L^{\infty}}\int\limits_{\substack{|u-x|\geq h\\ |u|<a}}\frac{1}{|u-x|}du\leq 2\|B\|_{L^{\infty}}\int\limits_{h\leq|u|\leq \frac{3a}{2}}\frac{1}{|u|}du=4\|B\|_{L^{\infty}}\ln\frac{3a}{2h}.
\end{equation*}
This proves \eqref{esti of Fw}. By \eqref{decom of Fw} and the dominated convergence theorem, the limit follows.

\label{general LAP}
    Let $H_d=-\Delta_{\mathbb{Z}^d}+V$ with a real-valued potential $V$ satisfying $|V(n)|\lesssim \left<n\right>^{-\beta}$ for some $\beta>2$ and $\mathcal{I}=(0,4d)\setminus\{4j: 1\leq j\leq d-1,\ j\in \mathbb{N}^+\}$. Let $[\beta]$ denote the greatest integer not exceeding $\beta$. Then the following statements hold.
\begin{itemize}
\item [\rm(i)] The point spectrum $\sigma_p(H_d)\cap\mathcal{I}$ is discrete, each eigenvalue has finite multiplicity, and the singular continuous spectrum $\sigma_{sc}(H_d)=\varnothing$.
\vskip0.2cm
\item [\rm(ii)] Let $j\in\left\{0,\cdots,[\beta]-2\right\}$ and $s>j+\frac{1}{2}$. Then 
the norm limits
    \begin{equation*}
   \frac{d^{j}}{d\lambda^j}(\mathcal{R}^{\pm}_V(\lambda))=\lim\limits_{\varepsilon\downarrow0}R^{(j)}_V(\lambda\pm i\varepsilon) \quad {\rm in} \quad \mathcal{B}(s,-s)
    \end{equation*}
exist and are norm-continuous on $\mathcal{I}\setminus\sigma_p(H_d)$. Here $R_{V}(z)=(H_d-z)^{-1}$ is the resolvent of $H_d$ and $R^{(j)}_{V}(z)$ denotes the $j$-th derivative of $R_{V}(z)$.
\end{itemize}

\label{def of regularity}
{\rm
Given an integer $k\in\mathbb{N}$, we say that $H_d$ belongs to the class $C^{k}(A)$, and write $H_d\in C^{k}(A)$, if the sesquilinear form $ad^{k}_{A}(H_d)$, initially defined on $\mathcal{D}(A^k)\times\mathcal{D}(A^k)$, extends continuously to $\ell^2(\mathbb{Z}^d)\times\ell^2(\mathbb{Z}^d)$. We identify this extension with the corresponding bounded operator on $\ell^2(\mathbb{Z}^d)$ and denote it by the same symbol. The iterated commutators $ad^{k}_{A}(H_d)$ are defined recursively by
\begin{align}\label{adk}
\begin{split}
ad^{0}_A(H_d)&=H_d,\quad
ad^{1}_{A}(H_d)=[H_d,A]=H_dA-AH_d,\\
ad^{k}_{A}(H_d)&=ad^{1}_{A}\left(ad^{k-1}_{A}(H_d)\right)=\sum\limits_{i,j\geq0,i+j=k}^{}\frac{k!}{i!j!}(-1)^{i}A^{i}H_dA ^{j}.
\end{split}
\end{align}
}

\label{mourre lemma}
 Let $H_d=-\Delta_{\mathbb{Z}^d}+V$ with $|V(n)|\lesssim \left<n\right>^{-\beta}$ for some $\beta>1$. For any $\lambda\in(0,4d)\setminus\{4j\}^{d-1}_{j=1}$, there exist constants $\delta,C>0$ and a compact operator $K$ such that
\begin{equation}\label{mourre estimate}
    E_{H_d}(J)[H_d,iA]E_{H_d}(J)\geq C E_{H_d}(J)+K,\quad J=(\lambda-\delta,\lambda+\delta),
\end{equation}
where $E_{H_d}(J)$ denotes the spectral projection of $H_d$ onto the interval $J$.

By the assumptions on $V$ and Weyl's theorem, the essential spectrum of $H$ satisfies 
$$\sigma_{ess}(H)=\sigma_{ess}(-\Delta_{\mathbb{Z}^3})=[0,12],$$
and the discrete spectrum $\sigma_{dis}(H)\subseteq\mathbb{R}\setminus[0,12]$.
Then, by Cauchy's integral formula, we have
\begin{align*}
e^{-itH}&=-\frac{1}{2\pi i}\ointctrclockwise_{|\omega|=C}e^{-it\omega}R_V(\omega)d\omega,\qquad C>\sup\{{12,\{|\lambda_j|\}_{\lambda_j\in\sigma_{dis}(H)}}\},\\
&=\sum\limits_{\lambda_j\in\sigma_{dis}(H)}e^{-it\lambda_j}\mathcal{P}_{\lambda_j}-\frac{1}{2\pi i}\int_{\Gamma(\varepsilon)}e^{-it\omega}R_V(\omega)d\omega,\quad 0<\varepsilon<1,
\end{align*}
where $\mathcal{P}_{\lambda_j}$ is the projection on the eigenspace corresponding to the eigenvalue $\lambda_j$ and the path $\Gamma(\varepsilon)$ is chosen as in Figure \ref{myplot} below. 
