\noindent Here the paths $\Gamma_{0\ell}(\varepsilon)$, $\Gamma^{\pm}_{j}(\varepsilon)$ and $\Gamma^{\pm}_{4k}(\varepsilon)$ are given as follows:
\begin{align}\label{expre of path Gammas}
\begin{split}
\Gamma_{01}(\varepsilon)&=\big\{|\omega|=\varepsilon~\big|~\arg\omega:\theta(\varepsilon)\to2\pi-\theta(\varepsilon)\big\},\quad {\rm sin}\theta(\varepsilon)=\varepsilon,\\
\Gamma^+_{j}(\varepsilon)&=\big\{\omega=\lambda+i\varepsilon^2~\big|~\lambda:4j-g(\varepsilon)\to4(j-1)+g(\varepsilon)\big\},\quad g(\varepsilon)=\varepsilon\sqrt{1-\varepsilon^2},\\
\Gamma^-_{j}(\varepsilon)&=\big\{\omega=\lambda-i\varepsilon^2~\big|~\lambda:4(j-1)+g(\varepsilon)\to4j-g(\varepsilon)\big\},\quad j=1,2,3,\\
\Gamma^{\pm}_{4k}(\varepsilon)&=\big\{|\omega-(4k\pm i\varepsilon^2)|=g(\varepsilon)~\big| \pm{\rm Im}\omega\geq\varepsilon^2\big\},\quad k=1,2,\\
\Gamma_{02}(\varepsilon)&=\big\{|\omega-12|=\varepsilon~\big|\arg(\omega-12):\pi+\theta(\varepsilon)\to3\pi-\theta(\varepsilon)\big\}.
\end{split}
\end{align}
Then
\begin{align}
&\qquad\quad e^{-itH}-   \sum\limits_{\lambda_j\in\sigma_{dis}(H)}e^{-it\lambda_j}\mathcal{P}_{\lambda_j}\notag\\
&=-\frac{1}{2\pi i}\lim\limits_{\varepsilon\downarrow0}\left[\sum\limits_{j=1}^{3}\int_{\underset{\pm}{\bigcup}\Gamma^{\pm}_j(\varepsilon)}e^{-it\omega}R_V(\omega)d\omega+\sum\limits_{k=1}^{2}\int_{\underset{\pm}{\bigcup}\Gamma^{\pm}_{4k}(\varepsilon)}e^{-it\omega}R_V(\omega)d\omega+\sum\limits_{\ell=1}^{2}\int_{\Gamma_{0\ell}(\varepsilon)}e^{-it\omega}R_V(\omega)d\omega\right]\notag\\
&=:-\frac{1}{2\pi i}\lim\limits_{\varepsilon\downarrow0}\Big(\sum\limits_{j=1}^{3}I_j(\varepsilon)+\sum\limits_{k=1}^{2}I_{4k}(\varepsilon)+\sum\limits_{l=1}^{2}I_{0\ell}(\varepsilon)\Big).\label{eitH}
\end{align}
\vskip0.2cm
\underline{\bf Case (1): $I_j(\varepsilon)$}. We prove that, for each $j=1,2,3$, 
\begin{equation}\label{Ij123}
\lim\limits_{\varepsilon\downarrow0}I_j(\varepsilon)=\int_{4(j-1)}^{4j}e^{-it\lambda}(\mathcal{R}^{-}_V-\mathcal{R}^{+}_{V})(\lambda)d\lambda\quad {\rm in}\ \ \mathcal{B}(\sigma,-\sigma),\quad \sigma>11/2. 
\end{equation}
Set $a_j=4(j-1)$. Fix $0<\mu_0\ll1$ sufficiently small and let  $0<\varepsilon<\mu_0$. Then  
\begin{align}\label{Ij}
\begin{split}
I_j(\varepsilon)&=\Big(\int_{\Gamma^+_j(\varepsilon)}+\int_{\Gamma^-_j(\varepsilon)}\Big)e^{-it\omega}R_V(\omega)d\omega\\
&=\Big(\int_{a_j+g(\varepsilon)}^{a_j+\mu_0}+\int_{a_j+\mu_0}^{a_{j+1}-\mu_0}+\int_{a_{j+1}-\mu_0}^{a_{j+1}-g(\varepsilon)}\Big)e^{-it\lambda}\Big(e^{-t\varepsilon^2}R_V(\lambda-i\varepsilon^2)-e^{t\varepsilon^2}R_V(\lambda+i\varepsilon^2)\Big)d\lambda\\
&=:I_{j1}(\varepsilon)+I_{j2}(\varepsilon)+I_{j3}(\varepsilon).
\end{split}
\end{align}
By Theorems \ref{Asymptotic expansion theorem_0} and \ref{Asymptotic expansion theorem_4}, the resolvent $R_V(a_j+\omega)$ near the threshold $a_j$ admits the unified expansion 
\begin{equation}\label{unified expan of Rv}
    R_V(a_j+\omega)=-\widetilde{\mathcal{P}}_{a_j}\omega^{-1}+\mathcal{E}_{a_j}(\omega), \quad 0<|\omega|\leq 2\mu_0,
\end{equation}
in the space $\mathcal{B}(\sigma,-\sigma)$. Here $\widetilde{\mathcal{P}}_{a_j}=\mathcal{P}_{a_j}$ if $a_j$ is an eigenvalue of $H$, and $\widetilde{\mathcal{P}}_{a_j}=0$ otherwise. Moreover, 
\begin{equation}\label{estim of mcaEaj}
    \|\mathcal{E}_{a_j}(\omega)\|_{\mathcal{B}(\sigma,-\sigma)}\lesssim|\omega|^{-1/2},\quad 0<|\omega|\leq2\mu_0.
\end{equation}
We first consider $I_{j1}(\varepsilon)$. Making the change of variables $x=\lambda-a_j$ and using \eqref{unified expan of Rv}, we obtain
\begin{align*}
    I_{j1}(\varepsilon)&=-\widetilde{\mathcal{P}}_{a_j}\int_{g(\varepsilon)}^{\mu_0}e^{-it(x+a_j)}\Big(  \frac{e^{-t\varepsilon^2}}{x-i\varepsilon^2}-\frac{e^{t\varepsilon^2}}{x+i\varepsilon^2}\Big)dx\\
&\quad+\int_{g(\varepsilon)}^{\mu_0}e^{-it(x+a_j)}\Big(e^{-t\varepsilon^2}\mathcal{E}_{a_j}(x-i\varepsilon^2)-e^{t\varepsilon^2}\mathcal{E}_{a_j}(x+i\varepsilon^2)\Big)dx\\
&:=I^{(1)}_{j1}(\varepsilon)+I^{(2)}_{j1}(\varepsilon).
\end{align*}
For fixed $t$ and sufficiently small  $\varepsilon$, we have
\begin{equation*}
    \Big|\frac{e^{-t\varepsilon^2}}{x-i\varepsilon^2}-\frac{e^{t\varepsilon^2}}{x+i\varepsilon^2}\Big|=\Big|\frac{x(e^{-t\varepsilon^2}-e^{t\varepsilon^2})+i\varepsilon^2(e^{-t\varepsilon^2}+e^{t\varepsilon^2})}{x^2+\varepsilon^4}\Big|\lesssim_t\frac{x\varepsilon^2+\varepsilon^2}{x^2+\varepsilon^4}.
\end{equation*}
Consequently,
\begin{equation}\label{I1j1}
    \|I^{(1)}_{j1}(\varepsilon)\|_{\mathcal{B}(\sigma,-\sigma)}\lesssim_t\varepsilon^2\Big(\int_{g(\varepsilon)}^{\mu_0}\frac{dx}{x}+\int_{g(\varepsilon)}^{\mu_0}\frac{dx}{x^2}\Big)\lesssim_t\varepsilon+\varepsilon^2|\ln g(\varepsilon)|\rightarrow0,\quad \varepsilon\rightarrow0.
\end{equation}
We next consider $I^{(2)}_{j1}(\varepsilon)$. By \eqref{estim of mcaEaj}, we note that 
\begin{equation*}
    \left\|e^{-it(x+a_j)}\Big(e^{-t\varepsilon^2}\mathcal{E}_{a_j}(x-i\varepsilon^2)-e^{t\varepsilon^2}\mathcal{E}_{a_j}(x+i\varepsilon^2)\Big)\right\|_{\mathcal{B}(\sigma,-\sigma)}\lesssim_t x^{-1/2}\in L^{1}((0,\mu_0]).
\end{equation*}
For every fixed $x\in (0,\mu_0]$, the limiting absorption principle gives
\begin{equation*}
\lim\limits_{\varepsilon\rightarrow0}\mathcal{E}_{a_j}(x\pm i\varepsilon^2)=\lim\limits_{\varepsilon\rightarrow0}\Big(R_V(a_j+x\pm i\varepsilon^2)+\widetilde{\mathcal{P}}_{a_j}(x\pm i\varepsilon^2)^{-1}\Big)=\mathcal{R}^{\pm}_V(a_j+x)+\widetilde{\mathcal{P}}_{a_j}x^{-1}.
\end{equation*}
Therefore, by Lebesgue's dominated convergence theorem, we obtain
\begin{equation}\label{I2j1}
\lim\limits_{\varepsilon\rightarrow0}I^{(2)}_{j1}(\varepsilon)=\int_{0}^{\mu_0}e^{-it(x+a_j)}(\mathcal{R}^-_V(x+a_j)-\mathcal{R}^+_V(x+a_j))dx=\int_{a_j}^{a_j+\mu_0}e^{-it\lambda}(\mathcal{R}^-_V(\lambda)-\mathcal{R}^+_V(\lambda))d\lambda.
\end{equation}
Similarly, we can also prove 
\begin{equation}\label{Ij3}
\lim\limits_{\varepsilon\rightarrow0}{I}_{j3}(\varepsilon)= \int_{a_{j+1}-\mu_0}^{a_{j+1}}e^{-it\lambda}(\mathcal{R}^-_V(\lambda)-\mathcal{R}^+_V(\lambda))d\lambda.
\end{equation}
It remains to consider the interior part $I_{j2}(\varepsilon)$. Let $J=[a_j+\mu_0,a_{j+1}-\mu_0]$. By the limiting absorption principle, the absence of embedded eigenvalues in the open spectral band, and the compactness of $J$, we have (cf. \cite[Proposition 2.6]{HY25})
\begin{equation*}
    \sup\limits_{\lambda\in J,\ 0<\varepsilon<\mu_0}\|R_V(\lambda\pm i\varepsilon^2)\|_{\mathcal{B}(\sigma,-\sigma)}<\infty.
\end{equation*}
Therefore, another application of the Lebesgue's dominated convergence theorem gives 
\begin{equation*}
\lim\limits_{\varepsilon\rightarrow0}{I}_{j2}(\varepsilon)= \int_{a_{j}+\mu_0}^{a_{j+1}-\mu_0}e^{-it\lambda}(\mathcal{R}^-_V(\lambda)-\mathcal{R}^+_V(\lambda))d\lambda.
\end{equation*}
Combining this limit with \eqref{I1j1}, \eqref{I2j1}, \eqref{Ij3}, and the decomposition \eqref{Ij}, we obtain \eqref{Ij123}.
\vskip0.2cm
\underline{\bf Case (2): $I_{4k}(\varepsilon)$}. We claim 
\begin{equation}\label{I4k}
\lim\limits_{\varepsilon\downarrow0}I_{4k}(\varepsilon)=\begin{cases}
0,&4k~\text{is a regular point of }H \\
-2\pi i e^{-4ikt} \mathcal{P}_{4k},&4k~\text{is an eigenvalue of }H
\end{cases}\quad {\rm in }\ \mathcal{B}(\sigma,-\sigma)
\end{equation}
with $\sigma>\frac{7}{2}$ in the regular case and $\sigma>\frac{11}{2}$ in the eigenvalue case. Indeed, for any $k=1,2$, recall 
\begin{equation}\label{I4keps}
    I_{4k}(\varepsilon)=\Big(\int_{\Gamma^+_{4k}(\varepsilon)}+\int_{\Gamma^-_{4k}(\varepsilon)}\Big)e^{-it\omega}R_V(\omega)d\omega=:I^+_{4k}(\varepsilon)+I^-_{4k}(\varepsilon).
\end{equation}
By \eqref{expre of path Gammas} and the change of variable $\omega=4k\pm i\varepsilon^2+g(\varepsilon) e^{i\theta}$, we have
\begin{equation*}
I^{\pm}_{4k}(\varepsilon)=ig(\varepsilon) e^{\pm t\varepsilon^2-4ikt}
\left\{
    \begin{aligned}
\int_{0}^{\pi}e^{i\theta-itg(\varepsilon) e^{i\theta}}R_V(4k+ i\varepsilon^2+g(\varepsilon )e^{i\theta})d\theta,&\quad ``+",\\
        \int_{\pi}^{2\pi}e^{i\theta-itg(\varepsilon) e^{i\theta}}R_V(4k- i\varepsilon^2+g(\varepsilon) e^{i\theta})d\theta,&\quad ``-".
    \end{aligned}
    \right.
\end{equation*}
(i) If $4k$ is a regular point of $H$, from \eqref{(t)asy expan of regular 4}, we have 
\begin{equation*}
\|R_V(4k+\omega)\|_{\mathcal{B}(\sigma,-\sigma)}\lesssim 1,\quad |\omega|\ll1/2, \quad \sigma>\frac{7}{2}.
\end{equation*}
Hence, 
\begin{equation}\label{lim of regular I4keps}
  \|I_{4k}(\varepsilon)\|_{\mathcal{B}(\sigma,-\sigma)} \leq\sum\limits_{\pm}\|I^{\pm}_{4k}(\varepsilon)\|_{\mathcal{B}(\sigma,-\sigma)}\lesssim g(\varepsilon) e^{|t|(g(\varepsilon)+ \varepsilon^2)}\rightarrow0,\quad \varepsilon\rightarrow0,\quad \sigma>\frac{7}{2}.
\end{equation}
(ii) If $4k$ is an eigenvalue of $H$, by \eqref{(t)asy expan eigenvalue 4}, as $|\omega|\ll 1/2$, 
\begin{equation*}
    R_V(4k+\omega)=-\mathcal{P}_{4k}\omega^{-1}+\widetilde{R}_V(4k+\omega),\quad {\rm in }~\mathcal{B}(\sigma,-\sigma),\quad \sigma>\frac{11}{2},
\end{equation*}
where $ \|\widetilde{R}_V(4k+\omega)\|_{\mathcal{B}(\sigma,-\sigma)}\lesssim |\omega|^{-\frac{1}{2}}$. Since $|g(\varepsilon) e^{i\theta}\pm i\varepsilon^2|^{-\frac{1}{2}}\lesssim \varepsilon^{-\frac{1}{2}}$, a similar argument to (i) yields
\begin{equation*}
\lim\limits_{\varepsilon\downarrow0}I^{\pm}_{4k}(\varepsilon)=-e^{-4ikt}\mathcal{P}_{4k}\lim\limits_{\varepsilon\downarrow0}\left\{\begin{aligned}
    \int_{0}^{\pi}\frac{ e^{i\theta-itg(\varepsilon) e^{i\theta}}}{\varepsilon(1-\varepsilon^2)^{-1/2}-ie^{i\theta}}d\theta,\quad ``+"\\
    \int_{\pi}^{2\pi}\frac{e^{i\theta-itg(\varepsilon) e^{i\theta}}}{-\varepsilon(1-\varepsilon^2)^{-1/2}-ie^{i\theta}}d\theta,\quad ``-"
\end{aligned}\right.=-\pi ie^{-4ikt}\mathcal{P}_{4k},
\end{equation*}
which together with \eqref{I4keps} and \eqref{lim of regular I4keps} gives \eqref{I4k}.

 \underline{\bf Case (3):  $I_{0\ell}(\varepsilon)$}. By Theorem \ref{Asymptotic expansion theorem_0} and an argument similar to $I_{4k}(\varepsilon)$, one can verify  
\begin{equation*}
\lim\limits_{\varepsilon\downarrow0}I_{01}(\varepsilon)~({\rm resp.~} I_{02}(\varepsilon))=\begin{cases}
    0,&0~({\rm resp.~12})~\text{is a regular point of}~ H\\
    0,&0~({\rm resp.~12})~\text{is a resonance of}~ H\\
    -2\pi i\mathcal{P}_0~ ({\rm resp.~}-2\pi ie^{-12it}\mathcal{P}_{12}),&0~({\rm resp.~12})~\text{is an eigenvalue of}~ H
\end{cases}
\end{equation*}
in $\mathcal{B}(\sigma,-\sigma)$ with $\sigma>5/2$ for the regular and resonance cases, and $\sigma>7/2$ for the eigenvalue case. Therefore, combining 
this formula and \eqref{eitH},\eqref{Ij123} and \eqref{I4k}, we obtain  \eqref{eitHpacH}.
